def edit_data(request, id):
    if request.method != "POST":
        return redirect('../dataelts')

    data_element = get_object_or_404(DataElement, pk=id)

    # récupération
    nom_donnee = request.POST.get('nom_donne')
    data_eltype = request.POST.get('data_eltype')
    aggregation = request.POST.get('aggregation')
    nature_donne = request.POST.get('nature_donne')
    default_value = request.POST.get('default_value')

    # ✅ checkbox FIX
    is_cumul = request.POST.get('null_conserv') is not None

    periode_debut_id = request.POST.get('periode_debut')
    periode_fin_id = request.POST.get('periode_fin')
    association = request.POST.get('association')

    # ✅ validation cumul
    if is_cumul:
        if not periode_debut_id or not periode_fin_id:
            messages.error(request, "Veuillez sélectionner les périodes.")
            return redirect(f'/edit_data/{id}')

    # conversion valeur
    try:
        default_value = int(default_value) if default_value else None
    except:
        default_value = None

    # update champs
    data_element.m_name = nom_donnee
    data_element.m_value_type = data_eltype
    data_element.m_aggregation_type = aggregation
    data_element.m_default_value = default_value
    data_element.m_domain_type = nature_donne
    data_element.is_zero_collect = is_cumul
    data_element.is_calcul = request.POST.get('is_calcul') is not None

    # logique cumul
    if is_cumul:
        data_element.periode_debut = get_object_or_404(PeriodeOk, pk=int(periode_debut_id))
        data_element.periode_fin = get_object_or_404(PeriodeOk, pk=int(periode_fin_id))
        data_element.define = True

        if association:
            data_element.parent = get_object_or_404(DataElement, pk=int(association))
        else:
            data_element.parent = None

    else:
        data_element.periode_debut = None
        data_element.periode_fin = None
        data_element.parent = None
        data_element.define = False



    data_element.save()

    messages.success(request, "Modification réussie")
    return redirect('/dataelts/')


