def ajax_restore(request):
    import random
    r_mail = request.GET.get('mail')
    code = ""
    for i in range(6):
        code += str(random.randint(0, 9))
    message_context = {
        'code': code,
    }
    subject = "  Compte Opera +"
    message = render_to_string('mails/new_code.html', message_context)
    email = r_mail
    email_from = settings.EMAIL_HOST_USER
    recipient_list = [email, ]
    msg = EmailMessage(subject, message, email_from, recipient_list)
    msg.content_subtype = 'html'
    try:
        msg.send()
        send = '0'
    except:
        send = '1'
    data = {
        'code': code,
        'send': send
    }
    return JsonResponse(data)


def restorepass(request):
    mail = request.POST['restore']
    password = request.POST['password']
    user = User.objects.filter(email=mail).first()
    user.set_password(password)
    user.save()
    login(request, user)
    return redirect('/')


