def log(request, out=False):
    if out == False:
        response = "/log_account/"
        result = False

        try:
            request.session['bad_log'] += 1
            if request.session['bad_log'] > 0:
                response = "/bad_auth/"
        except:
            request.session['bad_log'] = 1
            request.session['try_log'] = True

        r_email = request.POST.get('email')
        r_password = request.POST.get('password')

        users = User.objects.filter(email=r_email)
        r_username = users.last()

        if r_username is not None:
            r_username = r_username.username
            user = authenticate(username=r_username, password=r_password)

            if user:
                login(request, user)
                request.session['logged'] = 1
                request.session['bad_log'] = None

                # MODIFICATION ICI : On ajoute le tag "premiere_connexion" pour le JS
                messages.success(request, "premiere_connexion")
                return redirect("/institution/")

            else:
                if users.count() > 1:
                    for u in users:
                        user = authenticate(username=u.username, password=r_password)
                        if user:
                            login(request, user)
                            # MODIFICATION ICI AUSSI (pour le multi-compte)
                            messages.success(request, "premiere_connexion")
                            return redirect("/institution/")

                messages.error(request, "Email ou mot de passe incorrect ")

        else:
            messages.error(request, "Aucun compte trouvé avec cet email ")

        return redirect(response)

    else:
        logout(request)
        messages.success(request, "Déconnexion réussie ")
        return redirect("/")


