def specific_log(request, type_view=0):
    template = "specific_log.html"
    context = {

    }
    if type_view == 2:
        context['specific'] = 0  # Not Code
    return render(request, template, context)

def save_champs_dynamiques(request, entity_id):
    instance_entity = Entity.objects.get(id=int(entity_id))
    saved_count = 0
    for key, value in request.POST.items():
        if key.startswith('champ_'):
            champ_id = int(key.split('_')[1])
            champ = Champ.objects.get(id=champ_id)
            
            # ✅ UPDATE (respecte la contrainte unique)
            ChampValue.objects.update_or_create(
                champ=champ,
                entities=instance_entity,
                defaults={'value': value or None}
            )
            saved_count += 1
    
    messages.success(request, f'{saved_count} champs mis à jour')
    return saved_count



def save_entity_value(request):
   
    try:
        institution_id = int(request.POST['institution'])
        hierarchie_id = int(request.POST['hierachie'])
        fields_value = request.POST['fields']
        edit_or_create = request.POST['edit_or_create']
        is_tache = request.POST.get('is_tache') == 'True'
        sup_entity_id = request.POST.get('sup_entity')
        
        # 1. Récupération des valeurs du formulaire. 'None' est la valeur par défaut si le champ n'existe pas.
        accountable = request.POST.get('accountable')
        responsible = request.POST.get('perso')
        consulted = request.POST.get('consulted')
        informed = request.POST.get('informed')

        # Initialisation des variables à None pour s'assurer qu'elles existent, même si elles sont vides.
        instance_structure_responsible = None
        instance_structure_accountable = None
        instance_structure_consulted = None
        instance_structure_informed = None

       

        # --- Traitement de 'responsible' (ou 'perso') ---
        if responsible:  # Vérifie si la variable n'est pas None ET n'est pas une chaîne vide ('')
            try:
                instance_structure_responsible = Structure.objects.get(id=int(responsible))
            except (ValueError, ObjectDoesNotExist):
                # Ici, vous pouvez logger l'erreur ou ignorer simplement (ce que vous avez demandé)
                pass 

        # --- Traitement de 'accountable' ---
        if accountable:
            try:
                instance_structure_accountable = Structure.objects.get(id=int(accountable))
            except (ValueError, ObjectDoesNotExist):
                pass

        # --- Traitement de 'consulted' ---
        if consulted:
            try:
                instance_structure_consulted = Structure.objects.get(id=int(consulted))
            except (ValueError, ObjectDoesNotExist):
                pass

        # --- Traitement de 'informed' ---
        if informed:
            try:
                instance_structure_informed = Structure.objects.get(id=int(informed))
            except (ValueError, ObjectDoesNotExist):
                pass

        # Les variables 'instance_structure_...' contiendront soit l'objet Structure, soit None.
        # Le reste de votre code peut maintenant utiliser ces variables en toute sécurité.


    except KeyError as e:
        # Gérer le cas où une clé POST est manquante
        return HttpResponseBadRequest(f"Champs manquant dans le formulaire: {e}")

    dataset_ids = request.POST.getlist("dataset_id")
    instance_institution = get_object_or_404(Institution, id=institution_id)

    # 2. Détermination du type d'entité
    if hierarchie_id != -1:
        # S'il y a une hiérarchie spécifiée, on trouve le type d'entité correspondant.
        inst_entity = get_object_or_404(InsitutionEntities, m_hierachie=hierarchie_id, m_institution=instance_institution)
    else:
        # Sinon, on prend le dernier type d'entité de l'institution.
        inst_entity = InsitutionEntities.objects.filter(m_institution=instance_institution).last()
        if not inst_entity:
            # Gérer le cas où aucune entité n'est trouvée pour l'institution
            messages.error(request, "Aucun type d'entité trouvé pour cette institution.")
            return redirect('/gestionnaire/') # Redirection vers une page par défaut

    type_entity = inst_entity.m_entity_type

    # 3. Traitement des Tâches ou des Entités standard
    if is_tache:
        # Bloc de code pour la création ou l'édition d'une Tâche
        # ... (le code pour la gestion des Tâches que vous avez fourni, avec des ajustements)
        try:
            sup_entity = Entity.objects.get(id=int(sup_entity_id)) if sup_entity_id else None
        except (ValueError, Entity.DoesNotExist):
            sup_entity = None

        if sup_entity:
            # Cas avec parent
            existing_children = EntityHierachie.objects.filter(m_sup_entity=sup_entity)
            children_count = existing_children.count()
            new_ponderation = 100 / (children_count + 1)

            # Création de la nouvelle tâche (qui est aussi une Entity)
            entity = Tache(
                m_value_fields=fields_value,
                m_type_entity=type_entity,
                ponderation=new_ponderation,
                structure_responsable = instance_structure_responsible,
                structure_accountable = instance_structure_accountable,
                structure_consulted = instance_structure_consulted,
                structure_informed = instance_structure_informed,
                
                m_nom = request.POST.get('nom',''),
                objectif = request.POST.get('objectif',''),
                observation = request.POST.get('observation',''),
            )
            entity.save()



            if children_count > 0:
                existing_children_ids = existing_children.values_list('m_sub_entity_id', flat=True)
                Entity.objects.filter(id__in=existing_children_ids).update(ponderation=new_ponderation)

            EntityHierachie.objects.create(m_sup_entity=sup_entity, m_sub_entity=entity)
        
        else:
            # Gérer le cas où une tâche sans entité parente est créée
            entity = Tache.objects.create(m_value_fields=fields_value, m_type_entity=type_entity)

        # Mettre à jour les champs spécifiques de la tâche
        try:
            entity.montant = float(request.POST.get("finances", 0))
        except (ValueError, TypeError):
            entity.montant = 0
        entity.save()
        
        

        # Gestion des structures et rôles
        structures_list = request.POST['structures_list'].split('|')[:-1]
        structures_roles = request.POST['structures_roles'].split('\n')
        
        if edit_or_create == 'e':
            # Supprimer les structures existantes lors de l'édition
            entity.structures.all().delete()
        
        tmp_struc = sorted(list(set(structures_list)))
        
        for i, s_id in enumerate(tmp_struc):
            try:
                if s_id.strip() != '':
                    structure = Structure.objects.get(id=int(s_id))
                    role = structures_roles[i] if i < len(structures_roles) else ''
                    r_str = StructureRole(m_structure=structure, m_role=role)
                    r_str.save()
                    entity.structures.add(r_str)
            except (ValueError, Structure.DoesNotExist, IndexError):
                # Gérer les IDs invalides ou les rôles manquants
                continue
        
        entity.save() # Pour sauvegarder la relation ManyToMany
        
        # Gestion de la planification (TachePlannify)
        calendar = request.POST.get('calendar_selected')
        if calendar and calendar != "#":
            periode = get_object_or_404(Periode, id=int(request.POST['calendar_periode']))
            if edit_or_create == 'e':
                TachePlannify.objects.filter(m_tache=entity).delete()
            
            plani_tche = TachePlannify(m_tache=entity, m_planify=calendar, m_periode=periode)
            plani_tche.save()
            set_pv_tp(plani_tche)

    else:
        # Bloc de code pour la création ou l'édition d'une Entité standard
        if edit_or_create == 'e':
            edit_id = request.POST['edit_id']
            entity = get_object_or_404(Entity, id=int(edit_id))
            entity.m_value_fields = fields_value
            entity.m_type_entity = type_entity
        else:
            try:
                sup_entity = Entity.objects.get(id=int(sup_entity_id)) if sup_entity_id else None
            except (ValueError, Entity.DoesNotExist):
                sup_entity = None

            if sup_entity:
                # Cas avec parent
                existing_children = EntityHierachie.objects.filter(m_sup_entity=sup_entity)
                children_count = existing_children.count()
                new_ponderation = 100 if children_count == 0 else 100 / (children_count + 1)
                
                entity = Entity.objects.create(
                    m_value_fields=fields_value,
                    m_type_entity=type_entity,
                    structure_responsable = instance_structure_responsible,
                    structure_accountable = instance_structure_accountable,
                    structure_consulted = instance_structure_consulted,
                    structure_informed = instance_structure_informed,
                    ponderation=new_ponderation,
                    
                    m_nom = request.POST.get('nom',''),
                    objectif = request.POST.get('objectif',''),
                    observation = request.POST.get('observation',''),
                )

                print(f'entite: {entity}')



                if children_count > 0:
                    Entity.objects.filter(id__in=existing_children.values_list('m_sub_entity_id', flat=True)).update(ponderation=new_ponderation)

                # La création de la relation est gérée plus bas
            else:
                # Cas sans parent
                all_entities = Entity.objects.filter(m_type_entity=type_entity)
                new_count = all_entities.count() + 1
                new_ponderation = 100 / new_count

                entity = Entity.objects.create(
                    m_value_fields=fields_value,
                    m_type_entity=type_entity,
                    ponderation=new_ponderation,
                    structure_responsable = instance_structure_responsible,
                    structure_accountable = instance_structure_accountable,
                    structure_consulted = instance_structure_consulted,
                    structure_informed = instance_structure_informed,
                    
                    m_nom = request.POST.get('nom',''),
                    objectif = request.POST.get('objectif',''),
                    observation = request.POST.get('observation',''),
                )


                
                all_entities.update(ponderation=new_ponderation)
                
          
                
            
        
        # Gestion des Datasets
        manage_datasets(entity, dataset_ids)

        # Gérer la relation hiérarchique si une entité parente a été trouvée
        if sup_entity_id:
            try:
                sup_entity = Entity.objects.get(id=int(sup_entity_id))
                if edit_or_create == 'e':
                    # Supprimer l'ancienne relation si elle existe
                    EntityHierachie.objects.filter(m_sub_entity=entity).delete()
                
                EntityHierachie.objects.create(m_sub_entity=entity, m_sup_entity=sup_entity)
            except (ValueError, Entity.DoesNotExist):
                pass
        
    # 4. Gestion des fichiers et images (commun aux deux cas)
    try:
        if "cover_img" in request.FILES:
            entity.m_pic_represented = request.FILES["cover_img"]
            entity.save()
    except (IntegrityError, IOError):
        # Gérer les erreurs de fichier
        pass

    fields_name = entity.m_type_entity.fields()
    for i, f_type in enumerate(entity.m_type_entity.type_fields()):
        if f_type in ['file', 'image']:
            field_name = fields_name[i]
            if field_name in request.FILES:
                eF = EntityFile.objects.create(m_entity=entity, m_field=field_name, m_file=request.FILES[field_name])
                entity.set_value(field_name, str(eF.id))
            else:
                entity.set_value(field_name, "Aucun Fichier")
    
    entity.save()
    save_champs_dynamiques(request, entity.id)
   
                    
    base_val = request.POST.get("base_val")
    if base_val and base_val not in [' ', '0']:
        response_url = f"/gestionnaire/{hierarchie_id - 1}/{base_val}/"
    else:
        response_url = f"/gestionnaire/{hierarchie_id}/"

    messages.success(request, 'Enregistrement réussi !')
    return redirect(response_url)


def manage_datasets(entity, dataset_ids):
    """Gère l'association de l'entité aux datasets."""
    # Efface les datasets existants pour éviter les doublons ou les incohérences
    entity.dataset.clear()
    
    datasets_to_add = []
    for d_id in set(dataset_ids):
        try:
            datasets_to_add.append(DataSet.objects.get(id=int(d_id)))
        except (ValueError, DataSet.DoesNotExist):
            continue
    entity.dataset.add(*datasets_to_add)


