def set_new_password(request):
    # 1. Sécurité : Vérifier que l'utilisateur a bien validé l'OTP avant d'accéder à cette page
    reset_email = request.session.get('reset_email')
    
    if not reset_email:
        messages.error(request, "Accès non autorisé. Veuillez recommencer la procédure.")
        return redirect('/bad_auth/')

    if request.method == "POST":
        password = request.POST.get('password')
        confirm_password = request.POST.get('confirm_password')

        # 2. Vérification de la correspondance
        if password != confirm_password:
            messages.error(request, "Les mots de passe ne correspondent pas.")
            return redirect(request.META.get('HTTP_REFERER','/'))

        # 3. Récupération de l'utilisateur et mise à jour
        try:
            user = User.objects.get(username=reset_email)
            
            # Utilisation de set_password pour hacher le mot de passe (sécurité)
            user.set_password(password)
            user.save()

            # 4. Nettoyage de la session pour éviter de réutiliser le lien
            request.session.flush()

            messages.success(request, "Votre mot de passe a été réinitialisé avec succès. Vous pouvez vous connecter.")
            return redirect('/log_account/')

        except User.DoesNotExist:
            messages.error(request, "Une erreur est survenue. Utilisateur introuvable.")
            return redirect(request.META.get('HTTP_REFERER','/'))

    return render(request, '/presentation/')
def recup_password(request):
    if request.method == "POST":
        email = request.POST.get('email')
        
        # On vérifie si l'utilisateur existe (souvent l'email est dans le champ email, pas username)
        user = User.objects.filter(email=email).first()
        
        if user:
            # 1. Générer le code OTP (Note: randint avec un i minuscule)
            otp_code = random.randint(100000, 999999)
            
            # 2. Stocker l'OTP et l'email en session (plus sûr qu'un cookie visible)
            request.session['reset_otp'] = otp_code
            request.session['reset_email'] = email
            request.session['otp_timestamp'] = time.time()
            
            # 3. Envoyer l'email
            subject = "Votre code de récupération"
            message = f"Bonjour, votre code de réinitialisation est : {otp_code}"
            email_from = settings.DEFAULT_FROM_EMAIL
            recipient_list = [email]
            
            try:
                send_mail(subject, message, email_from, recipient_list)
                messages.success(request, "Un code de vérification a été envoyé à votre adresse email.")
                return redirect('/verify_otp_page/') # Redirige vers la page de saisie du code
            except Exception as e:
                messages.error(request, "Erreur lors de l'envoi de l'email. Réessayez plus tard.")
        else:
            # Sécurité : On affiche souvent le même message pour ne pas confirmer qu'un email existe
            messages.error(request, "Aucun compte n'est associé à cet email.")
            
    return render(request, 'votre_dossier/recup_password.html')
def verify_otp(request):
    if request.method == "POST":
        user_otp = request.POST.get('otp')
        session_otp = request.session.get('reset_otp')
        otp_time = request.session.get('otp_timestamp')
        
        # 1. Vérifier si les données existent en session
        if not session_otp or not otp_time:
            messages.error(request, "Session expirée. Veuillez redemander un code.")
            return redirect('/bad_auth/')

        # 2. Calculer la durée (ex: 300 secondes = 5 minutes)
        duree_validite = 300 
        temps_ecoule = time.time() - otp_time

        if temps_ecoule > duree_validite:
            # Supprimer les données expirées
            del request.session['reset_otp']
            del request.session['otp_timestamp']
            messages.error(request, "Le code OTP a expiré (limite de 5 min).")
            return redirect('/bad_auth/')

        # 3. Vérifier si le code est correct
        if str(user_otp) == str(session_otp):
            # Code valide ! On peut rediriger vers le changement de mot de passe
            return redirect('/new-password/')
        else:
            messages.error(request, "Code incorrect.")
            
    return render(request, 'verify_otp.html')        
           


