from django.shortcuts import redirect
from django.contrib import messages
from django.db import transaction
import datetime

def valid_actualite(request):
    # Il est préférable de vérifier la méthode dès le début
    if request.method != "POST":
        return redirect('/actualite/')

    try:
        # 1. Utilisation de .get() pour éviter un crash si un champ est manquant
        intitule = request.POST.get('intitule')
        description = request.POST.get('description')
        rubrique_id = request.POST.get('rubrique')
        sous_rubrique_id = request.POST.get('sous_rubrique')
        institution_id = request.POST.get('institution')
        
        # Récupération sécurisée du fichier
        photos = request.FILES.get('photos')

        # 2. Validation simple : s'assurer que les champs obligatoires sont là
        if not all([intitule, description, institution_id]):
            messages.error(request, "Veuillez remplir tous les champs obligatoires.")
            return redirect('/actualite/')

        # 3. Utilisation d'un bloc transaction pour garantir l'intégrité des données
        with db_transaction.atomic():
            # .create() sauvegarde déjà l'objet, le .save() suivant est inutile
            Actualite.objects.create(
                institution_id=institution_id,
                date=datetime.datetime.now(),
                intitule=intitule,
                description=description,
                photos=photos,
                rubrique_id=rubrique_id,
                sous_rubrique_id=sous_rubrique_id
            )

        messages.success(request, 'Actualité enregistrée avec succès')

    except Exception as e:
        print(f'erreur de soumission:{e}')
        messages.error(request, f"Une erreur est survenue lors de l'enregistrement.{e}")
        return redirect('/actualite/')

    return redirect('/actualite/')

