@require_POST
def AssociationCollaborator(request, id):
    """
    Associe ou désassocie intelligemment les collaborateurs pour un membre du personnel.
    """
    personnel = get_object_or_404(Personnel, id=id)

    # Récupère la liste des IDs cochés
    collaborateurs_ids = request.POST.getlist('collaborateurs')

    try:
        with db_transaction.atomic():  # assure que toutes les modifications passent ou échouent
            # IDs actuels
            actuels_ids = set(personnel.collaborateurs.values_list('id', flat=True))
            nouveaux_ids = set(map(int, collaborateurs_ids))

            # Calcul des ajouts et suppressions
            a_ajouter = nouveaux_ids - actuels_ids
            a_supprimer = actuels_ids - nouveaux_ids

            if a_ajouter:
                personnel.collaborateurs.add(*a_ajouter)
            if a_supprimer:
                personnel.collaborateurs.remove(*a_supprimer)

        messages.success(
            request, 
            f"Collaborateurs mis à jour avec succès pour {personnel.nom}."
        )

    except Exception as e:
        messages.error(
            request, 
            f"Erreur lors de la mise à jour des collaborateurs : {e}"
        )

    
    return redirect(request.META.get('HTTP_REFERER', '/'))
