def send_messages(request):
    # ✅ CORRECTION : Vérification HTMX NATIVE Django
    is_htmx = request.headers.get('HX-Request') == 'true'
    
    if request.method == 'POST':
        nom = request.POST.get('nom', '').strip()
        organisation = request.POST.get('organisation', '').strip()
        email = request.POST.get('email', '').strip()
        message = request.POST.get('message', '').strip()
        
        # Validation basique
        if not all([nom, email, message]):
            if is_htmx:
                return render(request, 'errors.html', {
                    'error': 'Tous les champs obligatoires doivent être remplis.'
                })
            return JsonResponse({'error': 'Champs manquants'}, status=400)
        
        if '@' not in email or '.' not in email:
            if is_htmx:
                return render(request, 'errors.html', {
                    'error': 'Email invalide.'
                })
            return JsonResponse({'error': 'Email invalide'}, status=400)
        
        # Contenu de l'email
        sujet = f"Nouvelle demande MEAL - {nom} ({organisation})"
        contenu = f"""
Nouvelle demande de contact reçue:

NOM: {nom}
ORGANISATION: {organisation}
EMAIL: {email}
MESSAGE: {message}

---
Envoyé depuis Opera+ Contact Form
        """
        
        try:
            send_mail(
                sujet,
                contenu,
                settings.DEFAULT_FROM_EMAIL,
                [
                    'henockmfouapon3@gmail.com',
                    'dairounjankouo2019@gmail.com'
                ],
                fail_silently=False,
            )
            
            if is_htmx:
                return render(request, 'partials/form_success.html')
            return JsonResponse({'success': 'Email envoyé !'})
            
        except Exception as e:
            logger.error(f"Erreur envoi email: {e}")
            if is_htmx:
                return render(request, 'errors.html', {
                    'error': 'Erreur lors de l\'envoi. Réessayez.'
                })
            return JsonResponse({'error': 'Erreur serveur'}, status=500)
    
    return JsonResponse({'error': 'Méthode non autorisée'}, status=405)

