from django.http import JsonResponse

def get_operations(request):
    # Récupérer les opérations avec le nom du personnel grâce à select_related
    operations = Operation.objects.select_related('personnel').values(
        'nom',
        'date_echeance',
        'personnel__nom'  # Assuming 'nom' is the field for the personnel's name
    )

    operations_list = list(operations)

    # A ce stade, chaque operation contiendra le nom du personnel sous la clé 'personnel__nom'
    for operation in operations_list:
        operation['nom_personne'] = operation.pop('personnel__nom')  # Récupérer le nom du personnel et le remplacer sous une nouvelle clé

    return JsonResponse(operations_list, safe=False)




def file_duplik(request, id):
  
    template = 'operations_clone.html'
    context = basis(request)
    actual_institution = context['actual_institution']
    context = basis(request)
    operation = get_object_or_404(Operation, id=int(id))
    context['operation'] = operation

    # Retrieve all datasets
    datasets = DataSet.objects.filter(m_institution=actual_institution)
    context['datasets'] = datasets
    periode_ok = PeriodeOk.objects.distinct('annee','nom')
    context['periode_ok'] =periode_ok
    structure= Structure.objects.filter(institution=actual_institution)

    personne = Personnel.objects.filter(actual_institution=actual_institution)
    context['personne'] = personne
    # Retrieve datasets associated with the operation
    operation_dataset = operation.dataset.all()
    context['operation_dataset'] = operation_dataset
    context['structure'] = structure
    dataset_None_operation = datasets.exclude(id__in=operation_dataset.values_list('id',flat=True))
    context['dataset_None_operation'] = dataset_None_operation
    nature = NatureOperation.objects.all()
    context['nature'] = nature
    categorie_operation = CategorieOperation.objects.filter(institution=context['actual_institution'])
    context['categorie_operation'] = categorie_operation
    maintenant = timezone.now().date()
    operations_delay = Operation.objects.filter(
    date_echeance__lt = maintenant, 
      m_institution = actual_institution,
    etat = 0
    ).count()
    context['operations_delay'] = operations_delay

    transaction_delay = IndicateurValeur.objects.filter(institution_id=actual_institution, date_enregistrement__lt = maintenant, etat_echeance = False).select_related('operation')
    context['transaction_delay'] = transaction_delay.count()    

    # ✅ TOUTES les EntityType tâches de l'institution + leurs Entity
    task_entity_types = EntityType.objects.filter(
        is_tache=True,
        insitutionentities__m_institution=actual_institution  # Jointure
    ).distinct()
    
    # Toutes les Entity liées à ces EntityType tâches
    task_entities = Entity.objects.filter(
        m_type_entity__in=task_entity_types
    ).select_related('m_type_entity')  

    context['task_entity_types'] = task_entity_types
    context['task_entities'] = task_entities
    # 1. Récupérer TOUTES les sources de financement disponibles
    # On filtre généralement par institution si tes sources sont spécifiques
    toutes_les_sources = SourceFinancement.objects.filter(institution = actual_institution) 

    # 2. Récupérer les montants déjà saisis pour cette opération spécifique
    financements_existants = FinancementOperation.objects.filter(operation=operation)
    
    # 3. Créer un dictionnaire pour mapper {id_source: montant_attribue}
    # On utilise 'montant_attribue' car c'est le nom dans ta base de données
    dict_finances = {f.source_financement_id: f.montant_attribue for f in financements_existants}

    # 4. Construire une liste hybride pour le template
    finances_globales = []
    for source in toutes_les_sources:
        finances_globales.append({
            'id': source.id,
            'nom': source.nom, 
            'montant': dict_finances.get(source.id, 0), 
            'is_linked': source.id in dict_finances
        })

    context['finances_globales'] = finances_globales


    return render(request,template,context)


