@transaction.atomic
def duplicate_operation(request, id):
    context = basis(request)
    actual_institution = context['actual_institution']

    # Attempt to retrieve the original item or raise 404 if not found
    try:
        original_item = Operation.objects.get(id=int(id))
    except Operation.DoesNotExist:
        raise Http404("Operation not found")

    # Creating a new object with the same attributes
    duplicated_item = Operation(
        nom=original_item.nom,
        personnel=original_item.personnel,
        code=original_item.code,
        accountable=original_item.accountable,
        informed=original_item.informed,
        consulted=original_item.consulted,
        date_echeance=original_item.date_echeance,
        m_institution=actual_institution,
        priorite = original_item.priorite,
        etat=original_item.etat,
        montant=original_item.montant,
        montant2=original_item.montant2,
        date_creation = original_item.date_creation,
        m_tache_plannification = original_item.m_tache_plannification,
        tache=original_item.tache,
        is_deleted = original_item.is_deleted,
        periode = original_item.periode,
        periode_ok = original_item.periode_ok,
        categorie = original_item.categorie,
        nature_operation = original_item.nature_operation,

    )

    # Save the duplicated object in the database
    duplicated_item.save()

    # If dataset is a ManyToMany field, replicate relationships
    duplicated_item.dataset.set(original_item.dataset.all())  # Make sure to handle many-to-many correctly

    # Success message
    messages.success(request, f'L\'operation "{duplicated_item.nom}" a été dupliqué avec succès.')

    # Redirecting to the previous page or a default fallback
    return redirect(request.META.get('HTTP_REFERER', '/'))

def gantt_planification(request):
    context = basis(request)
    actual_institution = context.get('actual_institution')
    
    if not actual_institution:
        return redirect('/no_institution/')

    operations = (
        Operation.objects
        .filter(m_institution=actual_institution, statut=0)
        .values(
            'id',

            'nom',
            'date_debut',
            'date_echeance',
            'date_creation',
            'priorite',

            'personnel__nom',
            'personnel__prenom',

            'accountable__nom',
            'accountable__prenom',

            'consulted__nom',
            'consulted__prenom',

            'informed__nom',
            'informed__prenom',
            'frequence',
            'tache__m_nom',
            
        )
    )

    operation_list = []

    for op in operations:
        operation_list.append({
            'id': op['id'],
            'nom': op['nom'],
            'tache': op['tache__m_nom'] or "Sans Tâche",
           
            'date_debut': (op['date_debut'] or op['date_creation']).isoformat(),
            'date_echeance': op['date_echeance'].isoformat() if op['date_echeance'] else None,
            'priorite': op['priorite'],

            'personnel': f"{op['personnel__prenom']} {op['personnel__nom']}" if op['personnel__nom'] else "—",
            'accountable': f"{op['accountable__prenom']} {op['accountable__nom']}" if op['accountable__nom'] else "—",
            'consulted': f"{op['consulted__prenom']} {op['consulted__nom']}" if op['consulted__nom'] else "—",
            'informed': f"{op['informed__prenom']} {op['informed__nom']}" if op['informed__nom'] else "—",
        })

    return JsonResponse(operation_list, safe=False)


def gantt(request):
    context = basis(request)
    actual_institution = context.get('actual_institution')
    
    if not actual_institution:
        return redirect('/no_institution/')
    
    maintenant = timezone.now()

    # On utilise .update() pour ajouter plusieurs valeurs d'un coup sans effacer l'existant
    context.update({
        'operation': Operation.objects.filter(m_institution=actual_institution, etat=2).count(),
        'operation_en_cours': Operation.objects.filter(m_institution=actual_institution, etat=1).count(),
        'total_operations': Operation.objects.filter(m_institution=actual_institution).count(),
       
    })

    template = 'gantt.html'
    return render(request, template, context)


from django.shortcuts import get_object_or_404, redirect
from django.contrib import messages
from .models import Structure, Operation, IndicateurValeur

def line_delete_structure(request, id):
    # 1. Récupération de l'objet
    structure = get_object_or_404(Structure, id=int(id))
    
    # 2. Vérification des relations avec les autres entités métiers
    # On exclut Structure d'ici pour traiter son arborescence proprement après
    models_to_check = [Operation, IndicateurValeur]
    can_delete = True

    for model in models_to_check:
        if model.objects.filter(structure=structure).exists():
            can_delete = False
            break

    # 3. Vérification de l'arborescence (Si la structure est le PARENT d'autres sous-structures)
 
    if can_delete:
        has_children = Structure.objects.filter(parent=structure).exists()
        if has_children:
            can_delete = False
            messages.error(
                request, 
                f"'{structure.nom}' ne peut pas être supprimée car elle est le parent d'autres sous-structures."
            )
            return redirect(request.META.get('HTTP_REFERER', '/'))

    # 4. Action de suppression ou message d'erreur général
    if can_delete:
        nom_structure = structure.nom  # Sauvegarde du nom avant suppression
        structure.delete()
        messages.success(request, f"La structure '{nom_structure}' a été supprimée avec succès.")
    else:
        messages.error(
            request, 
            f"Impossible de supprimer '{structure.nom}' : elle est liée à des opérations ou des valeurs d'indicateurs."
        )

    return redirect(request.META.get('HTTP_REFERER', '/'))


