def delete_role(request,id):
    role = Role.objects.get(id=int(id))

    allmodels = [Personnel_Function]

    for allmodel in allmodels:
        if allmodel.objects.filter(m_role=role).exists():
            messages.info(request,'Ce role ne peut etre supprime')
        else:
            role.delete()
            messages.success(request,'Role supprime')
    return redirect(request.META.get('HTTP_REFERER','/'))



def view_actuality(request, slug):
    # 1. On récupère l'objet principal par son slug
    # Utiliser get_object_or_404 est crucial pour éviter les crashs
    actualities = get_object_or_404(Actualite, slug=slug)
    
    # 2. On filtre les sous-actualités liées
    sous_actualite = SousActualite.objects.filter(actualite=actualities)
    
    
    context={
        'actualities' : actualities,
        'sous_actualite':  sous_actualite
        
        }
  
    
  
    
    # 4. Définition du template
    template = 'details_actualite.html'
    
    # /!\ TRÈS IMPORTANT : Il faut retourner le render /!\
    return render(request, template, context)

