def api_process(request):
    context = basis(request)
    actual_institution = context['actual_institution']

    if not actual_institution:
        return JsonResponse({'error': 'Institution not found'}, status=404)

    try:
        # Récupération de la valeur process directement depuis l'institution
        process_value = Institution.objects.get(id=actual_institution.id).process

        # Si process_value est None, on peut définir une valeur par défaut (0 par exemple)
        if process_value is None:
            process_value = 0

        # Assure que la valeur est bien un nombre et la limite entre 0 et 100
        try:
            process_value = float(process_value)
        except (TypeError, ValueError):
            process_value = 0

        process_value = max(0, min(100, process_value))

        return JsonResponse({
            'status': 'success',
            'data': process_value
        })

    except Institution.DoesNotExist:
        return JsonResponse({'error': 'Institution does not exist'}, status=404)
    except Exception as e:
        return JsonResponse({'error': str(e)}, status=500)








