def color(request):
    if request.method == 'POST':
        try:
            color = request.POST['color']
            color_fond = request.POST['color_fond']
            personnel_id = request.POST.get('personnel_id')

            # Validation basique
            if not color or not personnel_id:
                messages.error(request, "Données manquantes")
                return redirect(request.META.get('HTTP_REFERER', '/'))

            # Vérification que le personnel appartient bien à l'utilisateur
            personnel = Personnel.objects.get(id=int(personnel_id))
            personnel.color = color
            personnel.color_fond = color_fond
            personnel.save()

            messages.success(request, "Couleur mise à jour avec succès!")

        except Personnel.DoesNotExist:
            messages.error(request, "Profil personnel non trouvé")
        except ValueError:
            messages.error(request, "ID invalide")
        except Exception as e:
            messages.error(request, f"Erreur technique: {str(e)}")

    return redirect(request.META.get('HTTP_REFERER', '/'))

import pandas as pd
from django.contrib import messages
from django.shortcuts import redirect
from .models import Operation, Personnel  # Assurez-vous d'importer votre modèle Personnel
def upload_entity(request):
    if request.method == 'POST':
        try:
            file = request.FILES['file']
            tache = request.POST.get('tache')
            context = basis(request)
            actual_institution = context['actual_institution'].id

            # Lire le fichier Excel
            df = pd.read_excel(file)

            # Vérifier que les colonnes nécessaires existent
            required_columns = ['nom', 'ponderation']

            if not all(col in df.columns for col in required_columns):
                missing = [col for col in required_columns if col not in df.columns]
                raise ValueError(f"Colonnes manquantes dans le fichier Excel: {', '.join(missing)}")

            success_count = 0
            error_messages = []

            # Traitement ligne par ligne
            for index, row in df.iterrows():
                try:
                    # Fonction pour récupérer l'instance Personnel à partir de l'email
                   
                    # Récupérer les instances pour chaque rôle
                   
                    # Créer l'opération
                    Operation.objects.create(
                        nom=row['nom'],
                        ponderation=row['ponderation'],
                       
                        tache_id=tache,
                        m_institution_id=actual_institution
                    )
                    success_count += 1

                except Exception as e:
                    error_messages.append(f"Ligne {index + 2}: {str(e)}")
                    continue

            # Préparation du message de résultat
            result_message = f"{success_count} opération(s) créée(s) avec succès."
            if error_messages:
                result_message += f" {len(error_messages)} erreur(s) rencontrée(s)."
                messages.warning(request, result_message)
                messages.error(request, "Détails des erreurs : " + " | ".join(error_messages[:5]))  # Limite à 5 erreurs pour éviter la surcharge
            else:
                messages.success(request, result_message)

        except Exception as e:
            messages.error(request, f'Erreur lors du traitement du fichier: {str(e)}')

    return redirect(request.META.get('HTTP_REFERER', '/'))



def transaction(request, id):

   
    operation = IndicateurValeur.objects.get(id=int(id))

    context= basis(request)

    actual_institution = context['actual_institution']

    template = 'transaction.html'

    context['operation'] = operation

    rapport = OperationRapport.objects.all()

    context['rapport'] = rapport

    maintenant = timezone.now()
   

    operations_delay = Operation.objects.filter(
        date_echeance__lt = maintenant, 
        # personnel=request.user.personnel,
        m_institution = actual_institution,
        etat = 0
    ).count()
    context['operations_delay'] = operations_delay

    transaction_delay = IndicateurValeur.objects.filter(institution_id=actual_institution, date_enregistrement__lt = maintenant, etat_echeance = False).select_related('operation')
    context['transaction_delay'] = transaction_delay.count()      



    return render(request,template,context)
