def save_transaction(request):
    context = basis(request)
    date_now = datetime.datetime.now()
    actual_institution = context['actual_institution']

    if request.method != "POST":
        return redirect('/')

    try:
        # Validation des saisies
        history_id = request.POST.get('history')
        precision = request.POST.get('precision','')
        commentaire = request.POST.get('commentaire')
        operation_id = request.POST.get('operation_id')  # Récupération de l'ID de l'opération

        if not commentaire or not history_id or not operation_id:
            raise ValidationError("Le commentaire, l'ID d'opération et l'ID d'historique sont obligatoires.")

        # Récupération des données
        history = HistoricRACI.objects.get(id=int(history_id))

        # Récupération de l'objet Operation avant de créer l'indicateur
        operation_obj = Operation.objects.get(id=int(operation_id))

        file_uploaded = request.FILES.get('file')

        history.mail = request.POST.get('email')
        # Note: Cette ligne pourrait causer un problème si date_realisation n'est pas un format de date valide.
        history.date_soumission_transaction = date_now if request.POST.get(
            'date_realisation') is None else request.POST.get('date_realisation')
        history.m_commentaire = commentaire
        history.etat_transaction = True
        history.m_role = request.POST.get('role')
        history.file = file_uploaded if file_uploaded else None
        history.niveau_execution = precision if precision else request.POST.get('niveau_execution')

        # Save the history first
        history.save()

        # Création de l'indicateur en utilisant l'objet Operation
        indicateur = IndicateurValeur.objects.create(
            operation=operation_obj,  # Correction ici : on utilise l'objet, pas l'ID
            date_enregistrement=date_now if request.POST.get('date_realisation') is None else request.POST.get(
                'date_realisation'),
            type_donnee='DECLARATION',
            valeur=precision if precision else request.POST.get('niveau_execution',0),
        )
        indicateur.save()

        if file_uploaded:
            OperationRapport.objects.create(
                piece_jointe=file_uploaded,
                commentaire=commentaire,
                operation_id=history.id
            )

        messages.success(request, 'Transaction Soumise avec succès')
        return redirect('/alert_notifs/0/0/')

    except HistoricRACI.DoesNotExist:
        messages.error(request, "L'opération historique spécifiée n'existe pas.")
    except Operation.DoesNotExist:
        messages.error(request, "L'opération spécifiée n'existe pas.")
    except ValidationError as e:
        messages.error(request, str(e))
    except Exception as e:
        messages.error(request, f'Erreur de soumission : {str(e)}')

    return redirect('/alert_notifs/0/0/')


from django.http import JsonResponse
from .models import IndicateurValeur  # Assuming this is your model location
def get_transaction_data(request, operation_id):
    try:
        # Retrieve and sort transactions by date of record in chronological order.
        transactions = IndicateurValeur.objects.filter(operation_id=operation_id).order_by('date_enregistrement')

        # Check if any data exists.
        if not transactions.exists():
            return JsonResponse({
                'error': 'Aucune donnée trouvée',
                'categories': [],
                'previsionnel': [],
                'declarations': [],
                'validations': []
            })

        # Use a dictionary to group data by unique date
        data_by_date = {}
        for t in transactions:
            date_str = t.date_enregistrement.strftime('%Y-%m-%d')
            if date_str not in data_by_date:
                data_by_date[date_str] = {
                    'previsionnel': None,
                    'declarations': None,
                    'validations': None
                }

            # Populate the correct data point for the date
            if t.type_donnee == 'PREVISION':
                data_by_date[date_str]['previsionnel'] = float(t.valeur)
            elif t.type_donnee == 'DECLARATION':
                data_by_date[date_str]['declarations'] = float(t.valeur)
            elif t.type_donnee == 'VALIDATION':
                data_by_date[date_str]['validations'] = float(t.valeur)

        # Extract data from the dictionary into sorted lists
        categories = list(data_by_date.keys())
        previsionnel = [data_by_date[date]['previsionnel'] for date in categories]
        declarations = [data_by_date[date]['declarations'] for date in categories]
        validations = [data_by_date[date]['validations'] for date in categories]

        # Format the data for the JSON response.
        data = {
            'categories': categories,
            'previsionnel': previsionnel,
            'declarations': declarations,
            'validations': validations
        }

        return JsonResponse(data)

    except Exception as e:
        # Catch any unexpected errors and return a clean error message.
        return JsonResponse({
            'error': str(e),
            'categories': [],
            'previsionnel': [],
            'declarations': [],
            'validations': []
        }, status=400)
