from django.core.paginator import Paginator
from django.db.models import Prefetch

def planification_all_operations(request):
    try:
        # 1. Récupération de l'ID (gestion du POST et du GET pour la pagination)
        structure_id = request.POST.get('structures') or request.GET.get('structures')
        
        if not structure_id:
            return render(request, 'planification/results_fragment.html', {'operations': []})

        structure = Structure.objects.get(id=int(structure_id))

        # 2. Optimisation du QuerySet : 
        # - filter : on limite à la structure
        # - select_related : on récupère les FK liées en UNE SEULE requête
        # - only : on ne récupère que les colonnes nécessaires (gain mémoire énorme)
        operations_list = Operation.objects.filter(
            structure=structure
        ).select_related('structure', 'personnel').order_by('id')

        # 3. Pagination (Obligatoire pour 9 millions de lignes)
        paginator = Paginator(operations_list, 10) # 50 opérations par page
        page_number = request.GET.get('page', 1)
        page_obj = paginator.get_page(page_number)

        # 4. Contexte de base
        context_data = basis(request)
        actual_institution = context_data.get('actual_institution')

        # ATTENTION : Jamais de .all() sur 9M de lignes pour les transactions
        # On ne prend que les transactions liées à ces 50 opérations spécifiques
        operation_ids = [op.id for op in page_obj]
        transaction = IndicateurValeur.objects.filter(operation_id__in=operation_ids)

        context = {
            'structure': structure,
            'operations': page_obj, # On envoie l'objet page, pas le queryset brut
            'transaction': transaction,
            'responsables': Personnel.objects.filter(actual_institution=actual_institution)
        }

        return render(request, 'planification/results_fragment.html', context)

    except (Structure.DoesNotExist, ValueError):
        messages.error(request, "Structure non trouvée ou ID invalide.")
        return render(request, 'planification/results_fragment.html', {'operations': []})


