from itertools import groupby
from operator import attrgetter # Pour accéder facilement à l'attribut m_enti

def indicator_entities(request):
    context = basis(request)
    actual_institution = context['actual_institution']
    
    # 1. Récupérer et trier la liste par m_enti
    # C'est CRUCIAL pour que groupby fonctionne correctement.
    tous_les_indicateurs = Indicateur.objects.filter(m_institution=actual_institution).order_by('m_enti')

    indicateurvaleur = IndicateurValeur.objects.filter(type_donnee='cible')

    objectifs = IndicateurValeur.objects.filter(type_donnee='valeur_form')

    # 2. Grouper les indicateurs par m_enti
    # La clé de regroupement est l'attribut 'm_enti'
    grouped_indicators = {}
    for key, group in groupby(tous_les_indicateurs, key=attrgetter('m_enti')):
        # key est la valeur de m_enti (l'entité)
        # group est la liste des indicateurs associés à cette entité
        grouped_indicators[key] = list(group)

      

    # 3. Mettre le dictionnaire groupé dans le contexte
    context['grouped_indicators'] = grouped_indicators

    context['indicateurvaleur'] = indicateurvaleur

    context['objectifs']  = objectifs


    # Les variables heure_actuelle et valeur_aleatoire sont inutiles ici, mais je les laisse commentées.
    # heure_actuelle = datetime.datetime.now().strftime("%H:%M:%S")
    # valeur_aleatoire = random.randint(100, 999)

    return render(request, 'indicator_entities.html', context)


