def changeStatus(request):
    """
    Met à jour le statut d'une institution en fonction des données du formulaire POST.
    """
    # Seules les requêtes POST sont traitées
    if request.method == 'POST':
        try:
            # Assurez-vous que la fonction 'basis' est correctement définie et accessible.
            context = basis(request)
            actual_institution_id = context['actual_institution'].id

            # Récupérer les valeurs des cases à cocher.
            # Si une case est cochée, 'get' renvoie la valeur 'on'.
            # Si elle n'est pas cochée, 'get' renvoie None.
            is_step = request.POST.get('is_step')
            is_frequency = request.POST.get('is_frequency')
            
            # Récupérer l'objet Institution en utilisant l'ID
            institution = Institution.objects.get(id=int(actual_institution_id))

            # Mettre à jour les attributs de l'objet en fonction des cases à cocher
            if is_step:
                institution.is_step = True
            else:
                institution.is_step = False

            if is_frequency:
                institution.is_frequency = True
            else:
                institution.is_frequency = False

            # Sauvegarder l'objet Institution mis à jour.
            # Cette ligne doit être en dehors des 'if/else' pour être toujours exécutée.
            institution.save()

            messages.success(request, 'changement de status réalisé avec succès')
        except Exception as e:
            # Capturer et afficher les erreurs pour le débogage
            messages.error(request, f'erreur survenue: {e}')
    
    # Rediriger l'utilisateur vers la page précédente
    return redirect(request.META.get('HTTP_REFERER', '/'))


from django.views.decorators.http import require_http_methods
@require_http_methods(["POST"])
def save_etape(request):
    context=basis(request)
  
    # Check for the 'HX-Request' header to detect an HTMX request
    if request.headers.get('HX-Request'):
        # Get data from the POST request
        intitule = request.POST.get('intitule')
        progression = request.POST.get('progression')
        duree_faible = request.POST.get('duree_faible')
        duree_moyenne = request.POST.get('duree_moyenne')
        duree_grande = request.POST.get('duree_grande')
        nature_id = request.POST.get('nature')
        institution = request.POST.get('institution','')

        description = request.POST.get('description',None)

        numero_ordre = request.POST.get('numero_ordre')

        institution_ids = Institution.objects.get(id=int(institution))
        
        # Get the related Nature object
        try:
            nature = NatureOperation.objects.get(pk=nature_id)
        except NatureOperation.DoesNotExist:
            # Handle the case where the Nature object is not found
            return HttpResponse("Erreur: Nature introuvable.", status=400)
        
        # Create and save the new Etape object
        try:
            new_etape = Etape.objects.create(
                intitule=intitule,
                progression=progression,
                duree_faible=duree_faible,
                duree_moyenne=duree_moyenne,
                duree_grande=duree_grande,
                nature=nature,
                institution = institution_ids,
                description = description,
                numero_ordre = numero_ordre
            
            )
        except Exception as e:
            # Handle potential database save errors
            return HttpResponse(f"Erreur lors de l'enregistrement : {e}", status=500)

        # Return a rendered template snippet for the new table row
        # This is the line you need to change 
        return render(request, 'etape.html', {'etapes': [new_etape]})
    
    # If not an HTMX request, return a simple response
    return HttpResponse(status=204) # 204 No Content
def add_nature_operation(request):
    if request.method == "POST":
     
        intitule = request.POST.get('intitule')
        description = request.POST.get('description')
        institution_id = request.POST.get('institution')

        # Basic validation to ensure required fields aren't empty
        if not intitule:
            return HttpResponse("L'intitulé est un champ obligatoire.", status=400)

        add_nature_operation = NatureOperation.objects.create(
            intitule=intitule,
            description=description,
            institution_id=institution_id
        )
        return render(request,
            'list_natures.html',
            {'nature': [add_nature_operation]}
        )

    return HttpResponse("Méthode non autorisée.", status=405)
@require_http_methods(["DELETE"])
def delete_etape(request, id):
    # Utiliser get_object_or_404 pour gérer le cas où l'objet n'existe pas
    etape = get_object_or_404(Etape, id=id)

    dependent_models = [Operation]

    # Vérifier si l'étape est utilisée dans l'un de ces modèles
    for model in dependent_models:
        if model.objects.filter(etape=etape).exists():
           
            return HttpResponseForbidden("Cette étape ne peut pas être supprimée car elle est utilisée ailleurs.")

  
    etape.delete()

   
    return HttpResponse(status=200)
from django.db.models import Sum

def get_duree_field(intensite):
    """Retourne le nom du champ en base de données selon l'intensité."""
    mapping = {
        'FAIBLE': 'duree_faible',
        'MOYENNE': 'duree_moyenne',
        'GRANDE': 'duree_grande'
    }
    return mapping.get(intensite)

