def sum_duree(request):
    intensite = request.GET.get('intensite')
    context = basis(request)
    
    field = get_duree_field(intensite)
    total_duree = 0
    
    if field:
        total_duree = Etape.objects.filter(
            institution=context['actual_institution']
        ).aggregate(total=Sum(field))['total'] or 0

    context['total_duree'] = total_duree
    return render(request, 'configuration_admin.html', context)



