from django.shortcuts import get_object_or_404, render
from django.http import HttpResponse, QueryDict
from .models import Etape
from django.shortcuts import get_object_or_404, render
from django.http import HttpResponse, QueryDict

def update_etape(request, id):
    if request.method == "PUT":
        etape = get_object_or_404(Etape, id=id)

        # Manually parse the URL-encoded data from the request body
        data = QueryDict(request.body)

        # Get all fields
        intitule = data.get('intitule')
        progression = data.get('progression')
        duree_faible = data.get('duree_faible')
        duree_moyenne = data.get('duree_moyenne')
        duree_grande = data.get('duree_grande')
        nature_id = data.get('nature') # Get the ID from the select field
        description = data.get('description')

        numero_ordre = data.get('numero_ordre')




        etape.intitule = intitule
        etape.progression = progression
        etape.duree_faible = duree_faible
        etape.duree_moyenne = duree_moyenne
        etape.duree_grande = duree_grande
        etape.description = description
        etape.numero_ordre = numero_ordre
        if nature_id is None:
          
            etape.nature = get_object_or_404(NatureOperation, id=nature_id)

        etape.save()
        
        context = {'etape': etape}
        return render(request, 'etape_static_row.html', context)
    
    return HttpResponse(status=405)

def edit_structure_raci(request, id):
    if request.method == 'POST':
        try:
            # 1. Retrieve IDs from POST data, defaulting to None if key is missing/empty
            personnel_id = request.POST.get('perso')
            accountable_id = request.POST.get('accountable')
            consulted_id = request.POST.get('consulted')
            informed_id = request.POST.get('informed')

            # Initialize structure instances to None
            instance_structure_personnel = None
            instance_structure_accountable = None
            instance_structure_consulted = None
            instance_structure_informed = None

            # 2. Define a helper function to safely fetch the Structure instance
            def get_structure_instance(structure_id):
                if structure_id and structure_id.strip(): # Check if the ID is not None and not an empty string
                    try:
                        # Attempt to get the Structure object
                        return Structure.objects.get(id=int(structure_id))
                    except (ValueError, ObjectDoesNotExist):
                        # Catch if int() fails (not a number) or if object is not found
                        return None
                return None # Return None if the initial ID was empty or None

            # 3. Safely get the Structure instances
            instance_structure_personnel = get_structure_instance(personnel_id)
            instance_structure_accountable = get_structure_instance(accountable_id)
            instance_structure_consulted = get_structure_instance(consulted_id)
            instance_structure_informed = get_structure_instance(informed_id)

            # 4. Get the main Entity
            entity = Entity.objects.get(id=int(id))

            # 5. Assign the instances (can be None) to the entity fields
            entity.structure_responsable = instance_structure_personnel
            entity.structure_accountable = instance_structure_accountable
            entity.structure_consulted = instance_structure_consulted
            entity.structure_informed = instance_structure_informed

            # 6. Save the entity
            entity.save()

            messages.success(request, 'Mise à jour réussie') # Successful update message

            return redirect(request.META.get('HTTP_REFERER','/'))
            
        except ObjectDoesNotExist as e:
            # Catch error if the main Entity doesn't exist
            messages.error(request, f"Erreur de mise à jour: Entité non trouvée ou ID invalide.")
        except Exception as e:
            # Catch any other unexpected errors
            messages.error(request, f'Erreur de mise à jour: {e}')
            
    # Redirect back if not a POST request or after an error/success
    return redirect(request.META.get('HTTP_REFERER','/'))


def edit_cible(request):
    if request.method == 'POST':
        try:
            indicateur_valeur = request.POST.get('indicateur_valeur')

            structure = request.POST.get('structure')

            cible = request.POST.get('cible')
            is_referent = request.POST.get('is_referent') is not None

            indicateurvaleur = IndicateurValeur.objects.get(id=int(indicateur_valeur))

            instance_structure = Structure.objects.get(id=int(structure))


            indicateurvaleur.valeur = cible

            indicateurvaleur.structure = instance_structure
            
            indicateurvaleur.reference_cible =is_referent

            indicateurvaleur.save()

            messages.success(request,'Modification reussie')

        except Exception as e:

            messages.error(request,f'erreur survenue:{e}')
    return redirect(request.META.get('HTTP_REFERER','/'))

