class CustomLoginView(TokenObtainPairView):
    serializer_class = PersonnelEmailTokenObtainPairSerializer

    def post(self, request, *args, **kwargs):
        # Cette ligne de code est fondamentale dans l'héritage de classe en Python et Django REST Framework.
        response = super().post(request, *args, **kwargs)

        if response.status_code == 200:
            # Extraction des tokens
            access_token = response.data.pop('access')
            refresh_token = response.data.pop('refresh')
            user_data = response.data.pop('user', 'mail')

          

            # Configuration des cookies
            response.set_cookie(
                key=settings.SIMPLE_JWT['AUTH_COOKIE'],
                value=access_token,
                max_age=settings.SIMPLE_JWT['ACCESS_TOKEN_LIFETIME'].total_seconds(),
                secure=settings.SIMPLE_JWT['AUTH_COOKIE_SECURE'],
                httponly=settings.SIMPLE_JWT['AUTH_COOKIE_HTTP_ONLY'],
                samesite=settings.SIMPLE_JWT['AUTH_COOKIE_SAMESITE'],
                path=settings.SIMPLE_JWT['AUTH_COOKIE_PATH'],
            )

            response.set_cookie(
                key=settings.SIMPLE_JWT['AUTH_COOKIE_REFRESH'],
                value=refresh_token,
                max_age=settings.SIMPLE_JWT['REFRESH_TOKEN_LIFETIME'].total_seconds(),
                secure=settings.SIMPLE_JWT['AUTH_COOKIE_SECURE'],
                httponly=settings.SIMPLE_JWT['AUTH_COOKIE_HTTP_ONLY'],
                samesite=settings.SIMPLE_JWT['AUTH_COOKIE_SAMESITE'],
                path=settings.SIMPLE_JWT['AUTH_COOKIE_PATH'],
            )

            if user_data:
                response.data.update({'user': user_data})

        return response
from rest_framework.exceptions import PermissionDenied

class LogoutView(APIView):
    
    permission_classes = [IsAuthenticated]  # Permettre à tout le monde de se déconnecter
    def post(self, request):
        logout(request)

        response = Response(
            {'message': 'Déconnexion réussie'},
            status=status.HTTP_200_OK
        )

        # Suppression des cookies
        response.delete_cookie(settings.SIMPLE_JWT['AUTH_COOKIE'])
        response.delete_cookie(settings.SIMPLE_JWT['AUTH_COOKIE_REFRESH'])

        return response

