def devise_create(request):
    if request.headers.get('HX-Request'): 
        try:
            context = basis(request)
            actual_institution = context['actual_institution']
            code = request.POST.get('code').upper()
            symbole = request.POST.get('symbole')
            nom = request.POST.get('nom')
            taux = float(request.POST.get('taux', 1.0))
           
            
            devise = Devise.objects.create(
                code=code,
                symbole=symbole,
                nom=nom,
                taux_change=taux,
               
                institution = actual_institution
            )
            devise.save()
            message = 'Devise Enregistrée avec succès'
            return redirect(request.META.get('HTTP_REFERER','/'))
        except Exception as e:  
            return JsonResponse({'error': str(e)}, status=500)
        
            
            
           
           
         
    return JsonResponse({'error': 'Requête invalide'}, status=400)



def toggle_devise(request, id):
    devise = get_object_or_404(Devise, id=id)

    # récupérer l'institution connectée
    context = basis(request)
    actual_institution = context['actual_institution']

    message = None
    current = actual_institution.devise  # devise actuellement active

    # 🟢 CAS 1 — aucune devise active → on l'active
    if current is None:
        actual_institution.devise = devise
        actual_institution.save()
        message = "La devise a été activée avec succès."

    # 🟡 CAS 2 — il clique sur la même devise → rien à changer
    elif current == devise:
        message = "Cette devise est déjà active."

    # 🔵 CAS 3 — une autre devise est déjà active → on la remplace
    else:
        actual_institution.devise = devise
        actual_institution.save()
        message = "La devise active a été modifiée."

    return render(
        request,
        "partials/devise_switch.html",
        {
            "devises": devise,
            "message": message
        }
    )


