@login_required # Sécurité : assure que seul un utilisateur connecté peut changer de mot de passe
def changepassword(request, personnel_id=None):
    if request.method == 'POST':
        password1 = request.POST.get('password1')
        password2 = request.POST.get('password2')
        
        # 1. Vérification des champs
        if not password1 or not password2:
            messages.error(request, 'Veuillez remplir tous les champs.')
            return redirect(request.META.get('HTTP_REFERER', '/'))

        # 2. Vérification de la correspondance
        if password1 != password2:
            messages.error(request, 'Les mots de passe ne correspondent pas.')
            return redirect(request.META.get('HTTP_REFERER', '/'))

        # 3. Récupération de l'utilisateur
        # Si vous éditez un employé via une administration, utilisez personnel_id
        # Sinon, pour l'utilisateur connecté, utilisez request.user
        try:
            # Remplacez 'Personnel' par le nom de votre modèle si nécessaire
            # Si vous changez le mot de passe de l'utilisateur lié au personnel :
            user = User.objects.get(email=request.user.email) 
            
            # 4. Mise à jour
            user.set_password(password1)
            user.save()
            
            messages.success(request, 'Mot de passe mis à jour avec succès.')
            return redirect('/log_account/')
            
        except User.DoesNotExist:
            messages.error(request, 'Utilisateur introuvable.')
            return redirect(request.META.get('HTTP_REFERER', '/'))

    return redirect('/log_account/')



