from django.utils import timezone

def DetailRetard(request):
    context = basis(request)
    actual_institution = context.get('actual_institution')

    if not actual_institution:
        return no_institution(request)

   
    aujourdhui = timezone.now().date()
    
    # Récupération des objets avec leurs relations
    transactions = IndicateurValeur.objects.filter(
        institution=actual_institution, 
        date_enregistrement__lt=timezone.now(),
        etat_echeance = False
    ).select_related('operation').distinct().order_by('-date_enregistrement', 'id')


    p = Paginator(transactions, 10)  # creating a paginator object
    # getting the desired page number from url
    page_number = request.GET.get('page')
    try:
        page_obj = p.get_page(page_number)  # returns the desired page object
    except PageNotAnInteger:
        # if page_number is not an integer then assign the first page
        page_obj = p.page(1)
    except EmptyPage:
        # if page is empty then return last page
        page_obj = p.page(p.num_pages)

    for t in transactions:
       
        date_enreg = t.date_enregistrement
        if hasattr(date_enreg, 'date'):
            date_enreg = date_enreg.date()
            
        delta = aujourdhui - date_enreg
        t.jours_de_retard = delta.days
    transaction_delay = IndicateurValeur.objects.filter(institution=actual_institution, date_enregistrement__lt = aujourdhui, etat_echeance = False).select_related('operation')
    context['transaction_delay'] = transaction_delay.count()      
       

    context['transactions'] = transactions
    operations_delay = Operation.objects.filter(
            date_echeance__lt = aujourdhui, 
            personnel=request.user.personnel,
            etat = 0,
            etat_echeance = False
        ).count()
    context['page_obj'] = page_obj
    template = 'delay-transaction.html'
    return render(request, template, context)


import datetime
def send_mail_relance(request, transaction_id):
    if request.method == "POST":
        # 1. Récupération de la transaction
        transaction = get_object_or_404(IndicateurValeur, id=transaction_id)
        message_additionnel = request.POST.get('message', '')
        email_destinataire = transaction.operation.personnel.mail

        maintenant = timezone.now()

        delais = transaction.date_enregistrement

        retards = maintenant.date() - delais


        # 2. Préparation du contexte pour le design
        context = {
            'responsable': transaction.operation.personnel.nom,
            'operation_nom': transaction.operation.nom, # Ajustez selon votre modèle
            'jours_retard': retards.days,
            
            'date_debut': transaction.date_enregistrement,
            'message_perso': message_additionnel,
            'site_url': "https://operaplus.org" 
        }

        # 3. Génération du contenu HTML
        html_content = render_to_string('mails/send-relance.html', context)
        text_content = strip_tags(html_content) # Version texte brut pour les vieux clients mail

        # 4. Envoi du mail
        subject = f"🔔 ALERTE SUIVI : Retard sur l'opération {transaction.operation}"
        from_email = 'beininfo@operaplus.org'
        
        try:
            msg = EmailMultiAlternatives(subject, text_content, from_email, [email_destinataire])
            msg.attach_alternative(html_content, "text/html")
            msg.send()
            
            messages.success(request, f"La relance a bien été envoyée à {transaction.operation.personnel.nom}")
        except Exception as e:
            messages.error(request, f"Erreur lors de l'envoi : {e}")

    return redirect(request.META.get('HTTP_REFERER','/'))

