def organigramme(request):
    personnel_list = Personnel.objects.all().order_by('id') # Toujours ordonner pour une pagination stable
    
    # On définit le nombre d'éléments par page (ex: 10)
    paginator = Paginator(personnel_list, 8) 
    
    # On récupère le numéro de la page actuelle depuis l'URL (ex: ?page=2)
    page_number = request.GET.get('page')
    page_obj = paginator.get_page(page_number)
    
    context = basis(request)
    # On remplace 'personnel' par 'page_obj' qui contient les objets de la page actuelle
    context['personnel'] = page_obj 
    
    template = 'organigramme.html'
    return render(request, template, context)


def async_tache_retard(request):
    context = basis(request)
    actual_institution = context.get('actual_institution')
    maintenant = timezone.now()
    operations_delay = Operation.objects.filter(
        date_echeance__lt = maintenant, 
     
        m_institution = actual_institution,
        etat = 0
    ).count()
    return JsonResponse({'data': operations_delay})



