import random
import string
from django.contrib.auth.models import User
from django.utils import timezone
from django.http import JsonResponse
from django.utils.crypto import get_random_string

def register_expert(request):
    if request.method != "POST":
        return JsonResponse({"status": "error", "message": "Méthode non autorisée"}, status=405)

    try:
        email = request.POST.get('email')
        fullname = request.POST.get('fullname')
        
        if not email:
            return JsonResponse({"status": "error", "message": "L'email est requis"}, status=400)

        # 1. Gestion de l'utilisateur
        generator_password = None
        user_obj = User.objects.filter(username=email).first()

        if user_obj:
            expert = user_obj
        else:
            generator_password = get_random_string(length=12)
            expert = User.objects.create_user(
                username=email,
                email=email,
                first_name=fullname,
                password=generator_password
            )

        # 2. Mise à jour ou création du profil Personnel
        # Utilisation d'un dictionnaire pour les données afin de garder le code lisible
        personnel_data = {
            'tel': request.POST.get('whatsapp'),
            'country': request.POST.get('country'),
            'sexe': request.POST.get('gender'),
            'mail': email,
            'photo': request.FILES.get('photo'),
            'nom': fullname,
            'nationalite': request.POST.get('nationalite'),
            'parcours_meal': request.POST.get('parcours_meal'),
            'fonction': request.POST.get('skill'),
            'date_enregistrement': timezone.now()
        }

        # Générer le code seulement si le profil est créé pour la première fois
        personnel, created = Personnel.objects.get_or_create(bd_user=expert, defaults=personnel_data)
        
        if created:
            random_part = ''.join(random.choices(string.ascii_uppercase + string.digits, k=8))
            personnel.code = f"MEAL-AF-{personnel_data['country']}-{random_part}"
            personnel.save()
        else:
            # Mise à jour des champs si l'utilisateur existait déjà
            for key, value in personnel_data.items():
                setattr(personnel, key, value)
            personnel.save()

        # 3. Envoi au Broker (Celery)
        # On n'envoie le mot de passe que s'il a été généré
        if generator_password:
            send_expert_registration_email.delay({
                'fullname': fullname,
                'email': email,
                'password': generator_password
            })


        request.session['identification_user'] = expert.email
        request.session['identification_password'] = expert.password
        return JsonResponse({"status": "success"})

    except Exception as e:
        # En production, utilisez un logger au lieu de retourner l'erreur brute
        return JsonResponse({"status": "error", "message": f"Une erreur est survenue: {str(e)}"}, status=400)



def group_member_by_country(request):
    # Comptage des membres par code pays (alpha_2)
    personnel = Personnel.objects.filter(country__isnull=False)\
        .values('country')\
        .annotate(total=Count('id'))

    results = {}
    for data in personnel:
        alpha2 = data['country'].lower() 
        try:
            country_info = pycountry.countries.get(alpha_2=alpha2.upper())
            if country_info:
                num_code = country_info.numeric.zfill(3)
                results[num_code] = {
                    'total': data['total'],
                    'flag_code': alpha2,          
                    'name': country_info.name       
                }
        except Exception as e:
           
            continue

    return JsonResponse(results)
