def fallback_response(message):
    message = message.lower()

    # 🔥 règles simples intelligentes
    if "bonjour" in message or "salut" in message:
        return "👋 Salut ! Je suis là même sans connexion à l'IA."

    if "prix" in message or "coût" in message:
        return "💰 Nos services sont flexibles. Contacte-nous pour plus de détails."

    if "qui es-tu" in message:
        return "🤖 Je suis un assistant IA (mode hors ligne activé)."

    if "aide" in message:
        return "🆘 Je peux répondre aux questions simples même sans internet."

    # fallback générique
    return "⚠️ Je suis actuellement en mode hors ligne. Réessaie plus tard pour une réponse intelligente."


