import secrets
import string

def save_personnel_institution(request):
    context = basis(request)
    inst_actuelle = context.get('actual_institution')
    
    generator = request.POST.get('generator')
    edit_or_create = request.POST.get('edit_or_create')
    r_mail = request.POST.get('mail')
    
    if generator == "p2":
        # 1. Extraction des données
        r_nom = request.POST.get('nom')
        r_prenom = request.POST.get('prenom')
        r_tel = request.POST.get('tel')
        r_sexe = request.POST.get('sexe')
        r_poste = request.POST.get('poste', '')
        
        r_img = request.FILES.get('photo')
        
        # Gestion de l'image par défaut en création
        if not r_img and edit_or_create != 'e':
            default_file = OperaFile.objects.filter(m_name="USR").first()
            r_img = default_file.m_file if default_file else None

        # 2. Vérification existence
        user_exists = User.objects.filter(email=r_mail).first()
        personnel = Personnel.objects.filter(mail=r_mail).first()

        if edit_or_create != 'e':  # --- MODE CRÉATION ---
            if not user_exists:
                # Génération mot de passe et utilisateur
                alphabet = string.ascii_letters + string.digits
                password = ''.join(secrets.choice(alphabet) for i in range(8))
                username = f"user_{secrets.token_hex(4)}" 
                user = User.objects.create_user(username=username, email=r_mail, password=password)
                
                # Envoi de l'email
                try:
                    subject = "Nouveau Compte Opera +"
                    msg_html = render_to_string('mails/new_personnel.html', {
                        'password': password,
                        'name': f"{r_nom} {r_prenom}"
                    })
                    email = EmailMessage(subject, msg_html, settings.EMAIL_HOST_USER, [r_mail])
                    email.content_subtype = 'html'
                    email.send()
                except Exception as e:
                    messages.error(request,f"Erreur mail: {e}")
                
                messages.success(request, f"Le compte de {r_nom} a été créé.")
            else:
                # L'utilisateur existe déjà
                user = user_exists
                # On récupère la photo existante pour le modal
                p_existant = Personnel.objects.filter(bd_user=user).first()
                if p_existant and p_existant.photo:
                    request.session['temp_photo_url'] = p_existant.photo.url
                
                messages.info(request, "EXISTANT")

            # Création de la fiche personnel si elle n'existe pas encore
            if not personnel:
                personnel = Personnel.objects.create(
                    bd_user=user, nom=r_nom, prenom=r_prenom, mail=r_mail, 
                    photo=r_img, tel=r_tel, sexe=r_sexe, fonction=r_poste,
                    actual_institution=inst_actuelle
                )
        
        else:  # --- MODE ÉDITION ---
            edit_id = request.POST.get('edit_id')
            personnel = Personnel.objects.get(id=int(edit_id))
            personnel.nom, personnel.prenom = r_nom, r_prenom
            personnel.mail = r_mail
            personnel.tel = r_tel 
            if r_img: 
                personnel.photo = r_img
            
            if personnel.bd_user:
                personnel.bd_user.email = r_mail
                personnel.bd_user.save()
            personnel.save()
            messages.success(request, "Fiche mise à jour.")

        # 3. Liens Structure & Fonction (Correction MultipleObjectsReturned)
        struct_id = request.POST.get('Structure', '0')
        role_id = request.POST.get('Fonction')
        r_structure = Structure.objects.filter(id=int(struct_id)).first() if struct_id != '0' else None
        
        if role_id:
            try:
                r_role = Role.objects.get(id=int(role_id))

                # Gestion Personnel_Structure (Sécurisé)
                ps_link = Personnel_Structure.objects.filter(m_personnel=personnel).first()
                if ps_link:
                    ps_link.m_structure = r_structure
                    ps_link.save()
                else:
                    Personnel_Structure.objects.create(m_personnel=personnel, m_structure=r_structure)

                # Gestion Personnel_Function
                simple_user = request.POST.get('simple_user', '0')
                pf_defaults = {'m_role': r_role}
                if simple_user != '0':
                    entity = Entity.objects.filter(id=int(simple_user)).first()
                    if entity: pf_defaults['m_entity'] = entity

                Personnel_Function.objects.update_or_create(
                    m_personnel=personnel,
                    m_institution=inst_actuelle,
                    defaults=pf_defaults
                )
            except Role.DoesNotExist:
                pass

    return redirect("/personnels/")


def save_operation(request):
    context = basis(request)
    actual_institution = context.get('actual_institution')
    
    # Détection de la requête Fetch/AJAX
    is_ajax = request.headers.get('Accept') == 'application/json'

    try:
        r_tache_id = request.POST.get('tache')
        r_tache = Tache.objects.get(id=int(r_tache_id))
        
        # Helper pour récupérer le personnel unique
        def get_person(key):
            val = request.POST.get(key, "0")
            return Personnel.objects.get(id=int(val)) if val != "0" and val else None

        r_perso = get_person('perso')
        r_accountable = get_person('accountable')
        
        # Récupération des listes de checkboxes
        r_consulted = request.POST.getlist('consulted')
        r_informed = request.POST.getlist('informed')
        source_ids = request.POST.getlist('source_financement')

        # Dates et infos de base
        date_debut = request.POST.get('date_debut', '').strip()
        date_echeance_str = request.POST.get('date_echeance', '').strip()
        mois = request.POST.get('mois')
        structure_id = request.POST.get('structure', '').strip()
        
        instance_structure = None
        if structure_id and structure_id.isdigit():
            instance_structure = Structure.objects.get(id=int(structure_id))

        # Logique financière et pondération
        total_financement = Decimal(request.POST.get('total_financement', '0') or '0')
        all_operations = Operation.objects.filter(tache=r_tache)
        new_count = all_operations.count() + 1
        new_ponderation = 100 / new_count
        all_operations.update(ponderation=new_ponderation)

        # Création de l'opération
        operation = Operation.objects.create(
            tache=r_tache,
            nom=request.POST.get('nom'),
            notification=request.POST.get('notification'),
            priorite=request.POST.get('priorite'),
            date_echeance=date_echeance_str if date_echeance_str else None,
            date_debut=date_debut if date_debut else None,
            nature_operation_id=request.POST.get('nature'),
            categorie_id=request.POST.get('categorie'),
            structure=instance_structure,
            periode_ok_id=mois,
            parent_id=request.POST.get('operation_id') or None,
            ponderation=new_ponderation,
            nombre_jour=request.POST.get('nombre_jour', 0),
            montant_total_source_financement=total_financement,
            personnel=r_perso,
            accountable=r_accountable,
            m_institution=actual_institution,
            frequence=request.POST.get('frequence', '').strip()
        )

        # Enregistrement multiple pour Informed
        for perso_id in r_informed:
            if perso_id and perso_id != "0":
                try:
                    PersonnelInformed.objects.create(
                        operation=operation, 
                        informed_id=int(perso_id) 
                    )
                except Exception:
                    pass

        # Enregistrement multiple pour Consulted
        for perso_id in r_consulted:
            if perso_id and perso_id != "0":
                try:
                    PersonnelConsulted.objects.create(
                        operation=operation, 
                        consulted_id=int(perso_id) # Remplacez 'consulted_id' par le nom exact du champ dans votre modèle si nécessaire
                    )
                except Exception:
                    pass

        if 'file_oko' in request.FILES:
            operation.fichier_joint = request.FILES['file_oko']
            operation.save()

        # Mise à jour de la hiérarchie financière
        def update_hierarchy(current_entity, added_amount):
            current_entity.montant_planifiee = (current_entity.montant_planifiee or 0) + added_amount
            current_entity.save()
            parents = EntityHierachie.objects.filter(m_sub_entity=current_entity)
            for rel in parents:
                update_hierarchy(rel.m_sup_entity, added_amount)

        update_hierarchy(r_tache, total_financement)
        data_to_send = {}
        
        for s_id in source_ids:
            montant = request.POST.get(f'montant_source_{s_id}', '0')
            data_to_send[s_id] = montant

        # Envoi au broker Redis
        async_register_sources_financement.delay(
            operation.id, 
            actual_institution.id, 
            data_to_send
        )

        # Prévisions (Indicateurs)
        frequence_str = request.POST.get('frequence', '').strip()
        if frequence_str and date_debut and date_echeance_str:
            try:
                freq = int(frequence_str)
                d1 = datetime.datetime.strptime(date_debut, '%Y-%m-%d').date()
                d2 = datetime.datetime.strptime(date_echeance_str, '%Y-%m-%d').date()
                days_diff = (d2 - d1).days
                if freq > 0 and days_diff > 0:
                    steps = (days_diff // freq) + 1
                    percent_step = 100 / steps
                    for i in range(steps):
                        IndicateurValeur.objects.create(
                            operation=operation,
                            valeur=(i + 1) * percent_step,
                            type_donnee='PREVISION',
                            date_enregistrement=d1 + datetime.timedelta(days=(i + 1) * freq),
                            institution=actual_institution,
                            personnel=r_perso
                        )
            except ValueError:
                pass

        send_operation_mail.delay(operation.id)

        if is_ajax:
            return JsonResponse({'status': 'success', 'tache_id': r_tache.id})
        
        return redirect(f"/taches/{r_tache.id}/")

    except Exception as e:
        if is_ajax:
            return JsonResponse({'status': 'error', 'message': str(e)}, status=400)
        return redirect(request.META.get('HTTP_REFERER', '/'))


def count_transaction_and_tache_in_institution(request):
    context = basis(request)
    actual_institution = context.get('actual_institution')
    maintenant = timezone.now()

    # 1. Calcul des opérations
    operations_delay = Operation.objects.filter(
        date_echeance__lt=maintenant, 
        m_institution=actual_institution,
        etat=0
    ).count()

    # 2. Calcul des transactions (on prend directement le .count())
    transaction_delay_count = IndicateurValeur.objects.filter(
        institution_id=actual_institution, 
        date_enregistrement__lt=maintenant, 
        etat_echeance=False
    ).count()
    
    # On retourne les deux entiers
    return operations_delay, transaction_delay_count


def alert_supression(request, id):
    template = "infos-delete-operation.html"
    
    # Récupération de l'objet
    operation = Operation.objects.get(id=int(id))

    # APPEL DE LA MÉTHODE : On récupère les deux compteurs
    ops_count, trans_count = count_transaction_and_tache_in_institution(request)

    context = basis(request)
    context['operation'] = operation
    context['operations_delay'] = ops_count # Ajouté pour être complet
    context['transaction_delay'] = trans_count

    return render(request, template, context)



def detail_gantt(request, id):
    template = 'datails_gantt.html'

    ops_count, trans_count = count_transaction_and_tache_in_institution(request)

    context = basis(request)
    actual_institution = context['actual_institution']
    operation = Operation.objects.get(id=int(id))
    context['operation'] = operation
    context['operation'] = operation
    context['operations_delay'] = ops_count # Ajouté pour être complet
    context['transaction_delay'] = trans_count

    context['personnel'] = Personnel.objects.filter(actual_institution = actual_institution)


    operation_transaction = IndicateurValeur.objects.filter(institution_id = context['actual_institution'],  operation=operation)
    
    context['operation_transaction'] = operation_transaction

    
    return render(request, template, context)





def save_inst_settings(request, id):
    if request.method == "POST":
        try:
            inst = Institution.objects.get(id=id)
            data = json.loads(request.body)
            
            # 1. On récupère l'heure et on vérifie qu'elle n'est pas vide
            raw_hour = data.get('daily_hour')
            if not raw_hour or raw_hour.strip() == "":
                # On garde l'heure actuelle ou on met une heure par défaut
                daily_hour = inst.daily_digest_hour or "08:00"
            else:
                daily_hour = raw_hour

            # 2. Mise à jour sécurisée
            inst.alert_retard_active = data.get('alert_active', True)
            inst.minutes_avant_alerte = int(data.get('minutes', 0))
            inst.daily_digest_active = data.get('daily_active', False)
            inst.daily_digest_hour = daily_hour # Django validera le format ici
            inst.report_hebdo_active = data.get('hebdo_active', False)
            
            inst.save()
            return JsonResponse({"status": "ok"})
            
        except Exception as e:
            return JsonResponse({"status": "error", "message": str(e)}, status=400)


import pandas as pd
from django.http import JsonResponse

def check_periods(request):
    if request.method == 'POST' and request.FILES.get('file'):
        file = request.FILES['file']
        try:
            df = pd.read_excel(file)
            
            # CRUCIAL: Remplir les cellules vides (ex: la période 2020 qui s'applique aux lignes suivantes)
            df['periode'] = df['periode'].ffill() 
            
            # Nettoyer les valeurs nulles restantes et convertir en string pour la comparaison
            file_periods = df['periode'].dropna().unique().astype(str).tolist()
            
            db_periods = list(PeriodeOk.objects.values_list('annee', flat=True).map(str))
            
            missing = [p for p in file_periods if p not in db_periods]
            
            if missing:
                return JsonResponse({
                    'success': True,
                    'errors': [{'value': m, 'message': "Cette période n'est pas configurée."} for m in missing]
                })
            return JsonResponse({'success': True})
        except Exception as e:
            return JsonResponse({'success': False, 'errors': [{'value': 'Fichier', 'message': str(e)}]})

def check_orgunits(request):
    if request.method == 'POST' and request.FILES.get('file'):
        file = request.FILES['file']
        try:
            df = pd.read_excel(file)
            
            # Remplissage vers le bas pour la structure (SAQP)
            df['structure'] = df['structure'].ffill() 
            
            file_units = df['structure'].dropna().unique().astype(str).tolist()
            
            # Utilise le nom ou le code selon ce qui est dans l'Excel
            db_units = list(Structure.objects.values_list('nom', flat=True))
            
            missing = [u for u in file_units if u not in db_units]
            
            if missing:
                return JsonResponse({
                    'success': True,
                    'errors': [{'value': m, 'message': "Structure inconnue dans la hiérarchie."} for m in missing]
                })
            return JsonResponse({'success': True})
        except Exception as e:
            return JsonResponse({'success': False, 'errors': [{'value': 'Erreur', 'message': str(e)}]})



def check_elements(request):
    if request.method == 'POST' and request.FILES.get('file'):
        file = request.FILES['file']
        try:
            # Lire seulement la première ligne pour avoir les colonnes
            df = pd.read_excel(file, nrows=0)
            columns = df.columns.tolist()
            
            # On exclut les colonnes de contrôle
            excluded = ['periode', 'structure']
            file_elements = [c for c in columns if c not in excluded]
            
            # Vérifier si ces codes existent en BD
            db_elements = list(DataElement.objects.values_list('m_name', flat=True))
            
            missing = [e for e in file_elements if str(e) not in db_elements]
            
            if missing:
                return JsonResponse({
                    'success': True,
                    'errors': [{'value': m, 'message': "Code d'élément de donnée non reconnu."} for m in missing]
                })
            return JsonResponse({'success': True})
        except Exception as e:
            return JsonResponse({'success': False, 'errors': [{'value': 'Erreur', 'message': str(e)}]})

from asteval import Interpreter
def calculate_formula(formula, period, org_unit):
    """
    Calcule une formule d'indicateur du type:
    ($441$ / $442$) * 100
    """

    # 1. Extraire les data elements ($id$)
    ids = re.findall(r'\$(\d+)\$', formula)

    if not ids:
        return None

    # 2. Récupérer les valeurs en base (1 seule requête optimisée)
    values = DSet_DElt.objects.filter(
        m_dataelement_id__in=[int(i) for i in ids],
        periode=period,
        m_structure=org_unit
    ).values('m_dataelement_id').annotate(
        total=Sum('m_value')
    )

    # 3. Mapper les valeurs
    data_map = {
        str(v['m_dataelement_id']): (v['total'] or 0)
        for v in values
    }

    # 4. Remplacer les variables dans la formule
    expression = formula
    for id_ in ids:
        expression = expression.replace(
            f"${id_}$",
            str(data_map.get(id_, 0))
        )

    # 5. Calcul sécurisé
    try:
        aeval = Interpreter()
        return aeval(expression)
    except Exception:
        return None
def calculate_indicators(request):
    context = basis(request)
    actual_institution = context.get('actual_institution')

    data = json.loads(request.body)

    period = int(data.get("period"))
    org_unit = int(data.get("orgUnit"))
    indicators = data.get("indicators", [])

    results = []

    for ind_id in indicators:

        try:
            indicator = Indicateur.objects.get(id=ind_id)

            result = calculate_formula(
                indicator.m_numerateur,
                period,
                org_unit
            )

            if result is None:
                continue

            obj, created = IndicateurValeur.objects.update_or_create(
                indicateur=indicator,
                periode_ok_id=period,
                structure_id=org_unit,
                institution_id=actual_institution.id,
                type_donnee="valeur_form",
                defaults={
                    "valeur": result,
                    "date_enregistrement": timezone.now()
                }
            )

            results.append({
                "indicator": indicator.m_name,
                "value": result,
                "saved": created
            })

        except Exception as e:
            print("ERROR:", e)

    return JsonResponse({"results": results})

def run_indicator_calculation(period, org_unit, indicators, institution):

    print("RUNNING:", period, org_unit)

    for ind_id in indicators:
        try:
            indicator = Indicateur.objects.get(id=ind_id)

            print("IND:", indicator.m_name)
            print("FORMULA:", indicator.m_numerateur)

            result = calculate_formula(
                indicator.m_numerateur,
                period,
                org_unit
            )

            print("RESULT:", result)

            if result is None:
                print("SKIPPED")
                continue

            obj, created = IndicateurValeur.objects.update_or_create(
                indicateur=indicator,
                periode_ok_id=period,
                structure_id=org_unit,
                institution_id=institution.id,
                type_donnee="valeur_form",
                defaults={
                    "valeur": result,
                    "date_enregistrement": timezone.now()
                }
            )

            print("SAVED:", created)

        except Exception as e:
            print("ERROR:", e)
def final_import_data(request):
    context = basis(request)
    actual_institution = context.get('actual_institution')

    if request.method == 'POST' and request.FILES.get('file'):

        file = request.FILES['file']

        try:
            df = pd.read_excel(file)

            # 🔥 normalisation colonnes
            df.columns = [str(c).strip().lower() for c in df.columns]

           
            # 🔥 propagation valeurs fusionnées
            if 'structure' in df.columns:
                df['structure'] = df['structure'].ffill().astype(str).str.strip()

            if 'periode' in df.columns:
                df['periode'] = df['periode'].ffill().astype(str).str.strip()

            id_vars = [c for c in df.columns if c in ['structure', 'periode']]
            data_element_columns = [c for c in df.columns if c not in id_vars]

            df_melted = df.melt(
                id_vars=id_vars,
                value_vars=data_element_columns,
                var_name='element_nom',
                value_name='valeur'
            )

            print("TOTAL ROWS:", len(df_melted))

            stats = {'created': 0, 'updated': 0}
            error_details = []

            impacted_pairs = set()

            # =========================
            # 🔥 IMPORT DATA
            # =========================
            for index, row in df_melted.iterrows():

                try:
                    val = row['valeur']

                    if pd.isna(val) or val == "":
                        continue

                    structure_obj = Structure.objects.get(
                        nom__iexact=str(row['structure']).strip()
                    )

                    element_obj = DataElement.objects.get(
                        m_name__iexact=str(row['element_nom']).strip()
                    )

                    periode_obj = PeriodeOk.objects.get(
                        nom__iexact=str(row['periode']).strip()
                    )

                    obj, created = DSet_DElt.objects.update_or_create(
                        m_structure=structure_obj,
                        m_dataelement=element_obj,
                        periode=periode_obj,
                        defaults={
                            'm_value': int(float(val)),
                            'date_saisie': timezone.now().date()
                        }
                    )

                    trigger_analytics_calculation.delay(
                        data_element_id=element_obj.id, 
                        structure_id=structure_obj.id, 
                        periode_id=periode_obj.id
                    )

                    print("ADDED PAIR:", structure_obj.id, periode_obj.id)

                    impacted_pairs.add((structure_obj.id, periode_obj.id))

                    if created:
                        stats['created'] += 1
                    else:
                        stats['updated'] += 1
                    def launch_task(de_id, s_id, p_id):
                        print(f"DEBUG: Envoi direct vers Celery pour DE {element_id}")
                        trigger_analytics_calculation.apply_async(args=[int(element_id), int(structure_id), int(r_period2)])
                    
                    launch_task(data_element.id, structure_id, r_period2)


                except Structure.DoesNotExist:
                    error_details.append({
                        'message': f"Ligne {index+2}: Structure inconnue {row['structure']}"
                    })

                except DataElement.DoesNotExist:
                    error_details.append({
                        'message': f"Ligne {index+2}: DataElement inconnu {row['element_nom']}"
                    })

                except PeriodeOk.DoesNotExist:
                    error_details.append({
                        'message': f"Ligne {index+2}: Période inconnue {row['periode']}"
                    })

                except Exception as e:
                    error_details.append({
                        'message': f"Ligne {index+2}: {str(e)}"
                    })
                    print("ERROR LINE:", index, e)

            # =========================
            # 🔥 CALCUL INDICATEURS
            # =========================

            print("IMPACTED PAIRS:", impacted_pairs)

            if impacted_pairs:

                indicators_ids = list(
                    Indicateur.objects.values_list('id', flat=True)
                )

                for (structure_id, periode_id) in impacted_pairs:

                    print("RUN CALC:", structure_id, periode_id)

                    run_indicator_calculation(
                        period=periode_id,
                        org_unit=structure_id,
                        indicators=indicators_ids,
                        institution=actual_institution
                    )

            else:
                print("⚠️ NO IMPACTED PAIRS -> NO CALCULATION")

            return JsonResponse({
                'success': True,
                'message': f"{stats['created']} créations, {stats['updated']} mises à jour",
                'errors': error_details
            })

        except Exception as e:
            print("GLOBAL ERROR:", e)

            return JsonResponse({
                'success': False,
                'message': f"Erreur lecture fichier: {str(e)}"
            })

    return JsonResponse({
        'success': False,
        'message': "Aucun fichier reçu"
    })

def save_dataelts(request):
    if request.method != "POST":
        return redirect("/dataelts/")

    context = basis(request)

    r_nom = request.POST.get('nom')
    r_domain_type = request.POST.get('domain_type')
    r_value_type = request.POST.get('value_type')
    r_aggregation_type = request.POST.get('aggregation_type')
    nicename = request.POST.get('nicename')
    dataelts = request.POST.get('dataelts')

   
    r_null_conserv = request.POST.get('null_conserv')
    r_fill_valid = request.POST.get('fill_valid') == '1'

    r_logo = request.FILES.get('logo')

   
    dE = DataElement(
        m_name=r_nom,
        m_domain_type=r_domain_type,
        m_value_type=r_value_type,
        m_aggregation_type=r_aggregation_type,
        nicename=nicename if nicename else None,
        m_institution=context['actual_institution'],
        define = False
    )

    
    if r_logo:
        dE.m_logo = r_logo

  
    if r_fill_valid:
        default_value = request.POST.get('default_value')
        try:
            dE.m_default_value = int(default_value) if default_value else 0
        except ValueError:
            messages.error(request, "Valeur par défaut invalide.")
            return redirect("/dataelts/")
    else:
        dE.m_default_value = None

  
    periode_debut_id = request.POST.get('periode_debut')
    periode_fin_id = request.POST.get('periode_fin')

    
    if r_null_conserv:
        if not periode_debut_id or not periode_fin_id or not dataelts:
            messages.error(request, "Veuillez sélectionner les périodes début et fin pour une valeur cumulative ou le dataelement .")
            return redirect("/dataelts/")

        try:
            periode_debut = PeriodeOk.objects.get(id=int(periode_debut_id))
            periode_fin = PeriodeOk.objects.get(id=int(periode_fin_id))
            instance_dataelement = DataElement.objects.get(id=int(dataelts))
        except (ValueError, PeriodeOk.DoesNotExist):
            messages.error(request, "Périodes invalides.")
            return redirect("/dataelts/")

        dE.periode_debut = periode_debut
        dE.periode_fin = periode_fin
        dE.parent = instance_dataelement
        dE.define = True

    
    dE.save()

    messages.success(request, 'Enregistrement réussi')
    return redirect("/dataelts/")


def details_cumul(request, id):
    template = "detail-cummul.html"
    dataelt = get_object_or_404(DataElement, id=id)

    # 1. On récupère la valeur textuelle (m_value) de la périodicité de début
    if dataelt.periode_debut and dataelt.periode_debut.periodicite:
        periodicite_cible = dataelt.periode_debut.periodicite.m_value
    else:
        periodicite_cible = 'Mensuel'

    # 2. On filtre en traversant jusqu'à m_value
    dset_delts = DSet_DElt.objects.filter(
        m_dataelement=dataelt,
        periode__periodicite__m_value=periodicite_cible # <-- CORRECTION ICI
    ).select_related('periode', 'm_structure').order_by('periode__numero_ordre')

