from celery.result import AsyncResult
def import_periods_view(request):
    if request.method == "POST" and request.FILES.get("file"):
        uploaded_file = request.FILES["file"]
        
        # Sauvegarde du fichier
        path = default_storage.save(f'tmp/{uploaded_file.name}', ContentFile(uploaded_file.read()))
        full_path = default_storage.path(path)

        dry_run = request.POST.get("dry_run") == "true"
        update_mode = request.POST.get("update") == "true"

        
        task = import_data_to_database.delay(full_path, update_mode, dry_run)

        # Maintenant 'task.id' est accessible
        return JsonResponse({
            "status": "processing",
            "task_id": task.id
        })
    
    # Optionnel : gérer le cas où ce n'est pas un POST ou s'il manque le fichier
    return JsonResponse({"status": "error", "message": "Requête invalide"}, status=400)

def check_import_status(request, task_id):
    """Vue pour vérifier si la tâche est terminée"""
    res = AsyncResult(task_id)
    if res.ready():
        # res.result contient le dictionnaire {'created': 15303, ...}
        return JsonResponse({"status": "done", "result": res.result})
    return JsonResponse({"status": "pending"})
def dynamic_cible(request, id):
    context = basis(request)
    actual_institution = context.get('actual_institution')
    template = "dynamic-cible.html"
    
    indicateur = Indicateur.objects.get(id=int(id))
    structures = Structure.objects.filter(institution=actual_institution)
    periodes = actual_institution.get_periodes_actif()

    valeurs_existantes = IndicateurValeur.objects.filter(indicateur=indicateur, type_donnee="valeur")
    
    # On crée un dictionnaire : {(structure_id, periode_id): valeur}
    mapping_valeurs = {
        (int(v.structure_id), int(v.periode_ok_id)): v.valeur
        for v in valeurs_existantes
    }
 

    context['periodes'] = periodes
    context['structures'] = structures
    context['indicateur'] = indicateur
    context['mapping_valeurs'] = mapping_valeurs

    return render(request, template, context)


import json
from django.http import JsonResponse
from .models import IndicateurValeur, Structure, Periode



def save_meal_data(request):
    if request.method == 'POST':
        try:
            # 1. Chargement des données
            data = json.loads(request.body)
            indicateur_id = data.get('indicateur_id')
            lignes = data.get('donnees', [])
            
            # 2. Récupération de l'institution via ta fonction basis
            context = basis(request)
            actual_institution = context.get('actual_institution')

            for ligne in lignes:
                structure_id = ligne.get('structure_id')
                valeurs = ligne.get('valeurs_periodiques', {})

                for p_id, val in valeurs.items():
                    # --- FILTRES DE SÉCURITÉ ---
                    # On ignore la baseline et les cases vides
                    if p_id == 'baseline' or val == "" or val is None:
                        continue

                    # Conversion sécurisée des IDs et de la valeur
                    try:
                        idx_id = int(indicateur_id)
                        str_id = int(structure_id)
                        per_id = int(p_id)
                        val_float = float(val)
                    except (ValueError, TypeError):
                        continue

                    # --- GESTION DES DOUBLONS ---
                    # On cherche tous les enregistrements correspondants
                    records = IndicateurValeur.objects.filter(
                        indicateur_id=idx_id,
                        structure_id=str_id,
                        periode_ok_id=per_id,
                        type_donnee="valeur",
                        institution=actual_institution
                    )

                    if records.exists():
                        # S'il y en a plusieurs (ton erreur 400), on met à jour le premier
                        # et on pourrait supprimer les autres si nécessaire
                        obj = records.first()
                        obj.valeur = val_float
                        obj.date_enregistrement = timezone.now()
                        obj.save()
                    else:
                        # Si aucun n'existe, on crée proprement
                        IndicateurValeur.objects.create(
                            indicateur_id=idx_id,
                            structure_id=str_id,
                            periode_ok_id=per_id,
                            type_donnee="valeur",
                            institution=actual_institution,
                            valeur=val_float,
                            date_enregistrement=timezone.now()
                        )

            return JsonResponse({'status': 'success', 'message': 'Données enregistrées'})

        except Exception as e:
            # On affiche l'erreur dans le terminal pour le debug
            print(f"!!! ERREUR SAVE : {str(e)}")
            return JsonResponse({'status': 'error', 'message': str(e)}, status=400)

    return JsonResponse({'status': 'error', 'message': 'Méthode non autorisée'}, status=405)



def meal_dashboard_analytics(request, indicateur_id):

    try:
        indicateur = Indicateur.objects.get(id=indicateur_id)
    except Indicateur.DoesNotExist:
        return JsonResponse({"error": "Indicateur introuvable"}, status=404)
    context = basis(request)
    actual_institution = context.get('actual_institution')
    periodes = actual_institution.get_periodes_actif()
    structures = list(Structure.objects.filter(institution=actual_institution))

    labels = [p.nom for p in periodes]

    datasets = []

    for s in structures:

        data = []

        for p in periodes:

            val = (
                IndicateurValeur.objects
                .filter(
                    indicateur_id=indicateur_id,
                    structure=s,
                    periode_ok=p,
                    type_donnee="valeur"
                )
                .values_list("valeur", flat=True)
                .first()
            )

            data.append(float(val or 0))

        datasets.append({

            "label": s.nom,
            "data": data,

            "borderColor": None,
            "tension": 0.3,
            "fill": False,
            "pointRadius": 3

        })

    return JsonResponse({

        "labels": labels,
        "datasets": datasets,

        "indicateur": indicateur.m_name
    })




