def analyse_data(request, id):
    context = basis(request)
    actual_institution = context.get('actual_institution')
    indicateur = Indicateur.objects.get(id=int(id))

    periodes = actual_institution.get_periodes_actif()
    
    
   

    labels = [p.nom for p in periodes]
    datasets = []
    
    total_cible = 0
    total_realisation = 0


    realisation_data = []
    cible_data = []
    
    for p in periodes:
        # Récupération des points de données
        points = IndicateurValeur.objects.filter(
            indicateur_id=indicateur,
         
            periode_ok=p
        )

        # Accès aux valeurs via le type_donnee
        cible = float(points.filter(type_donnee="valeur").values_list("valeur", flat=True).first() or 0)
        realisation = float(points.filter(type_donnee="valeur_form").values_list("valeur", flat=True).first() or 0)

        realisation_data.append(realisation)
        cible_data.append(cible)
        
        total_cible += cible
        total_realisation += realisation

    # Ajout des deux séries au graphique
    datasets.append({
        "label": f"(Réalisé)",
        "data": realisation_data,
        "is_target": False
    })
    datasets.append({
        "label": f"(Cible)",
        "data": cible_data,
        "is_target": True
    })

    taux_global = round((total_realisation / total_cible) * 100, 2) if total_cible > 0 else 0

    return JsonResponse({
        "labels": labels,
        "datasets": datasets,
        "taux_realisation": taux_global,
        "indicateur": indicateur.m_name
    })


from django.db.models import Sum, Avg
from django.http import JsonResponse
from django.db.models import Sum, Avg, Max, Min
from django.http import JsonResponse

def aggregation_indicator(request, id):
    """
    Moteur d'agrégation complet pour les indicateurs MEAL.
    Gère les types : Somme, Moyenne, Maximum, Minimum, Compteur, Dernière valeur.
    """
    try:
        # 1. Récupération de l'indicateur
        obj_indicateur = Indicateur.objects.get(id=id)
        
        # 2. Filtrage des données (uniquement les saisies de formulaire)
        valeurs_qs = IndicateurValeur.objects.filter(
            indicateur=obj_indicateur, 
            type_donnee="valeur_form"
        )

        resultat = 0
        agg_type = obj_indicateur.type_aggregation # Récupère le choix du select HTML

        # 3. Logique d'agrégation exhaustive
        if agg_type == "Somme":
            resultat = valeurs_qs.aggregate(res=Sum('valeur'))['res'] or 0

        elif agg_type == "Moyenne":
            resultat = valeurs_qs.aggregate(res=Avg('valeur'))['res'] or 0

        elif agg_type == "Maximum":
            resultat = valeurs_qs.aggregate(res=Max('valeur'))['res'] or 0

        elif agg_type == "Minimum":
            resultat = valeurs_qs.aggregate(res=Min('valeur'))['res'] or 0

        elif agg_type == "Compteur":
            # Compte le nombre d'entrées SQL
            resultat = valeurs_qs.count()

        elif agg_type == "Dernière valeur":
            # Récupère la saisie la plus récente (tri par date puis par ID)
            derniere_entree = valeurs_qs.order_by('-date_saisie', '-id').first()
            resultat = derniere_entree.valeur if derniere_entree else 0

        # 4. Réponse JSON formatée pour ApexCharts ou tes Dashboards
        return JsonResponse({
            "status": "success",
            "indicator_id": id,
            "indicator_name": obj_indicateur.m_name,
            "aggregation_applied": agg_type,
            "value": float(resultat) # Conversion pour la compatibilité JSON
        })
      
    except Indicateur.DoesNotExist:
        return JsonResponse({"status": "error", "message": "Indicateur non trouvé"}, status=404)
    except Exception as e:
        print(f"--- ERREUR AGGREGATION (ID:{id}) --- : {str(e)}")
        return JsonResponse({"status": "error", "message": "Erreur lors du calcul des données"}, status=500)


