def get_xaf_to_eur_rate():
    # On regarde si le taux est déjà dans le cache
    rate = cache.get('xaf_to_eur_rate')
    
    if not rate:
        # Appel API si le cache est vide
        api_key = '7e806f92320f4c56be0d253b32947ef7'
        url = f"https://api.currencyfreaks.com/v2.0/rates/latest?apikey={api_key}&symbols=EUR,XAF"
        
        try:
            response = requests.get(url).json()
            rates = response['rates']
            # Calcul : (1 / taux_XAF) * taux_EUR
            rate = float(rates['EUR']) / float(rates['XAF'])
            
            # Stocker en cache pour 24h (86400 secondes)
            cache.set('xaf_to_eur_rate', rate, 86400)
        except Exception:
            rate = 0.00152 # Taux de secours
            
    return rate
from decimal import Decimal
def liste_packages(request):
    template = 'package.html'
    
    # 1. Récupération des données
    packages = Package.objects.all()
    
    # 2. Récupération du taux et conversion en Decimal
    rate = get_xaf_to_eur_rate() # Votre taux (float)
    rate_decimal = Decimal(str(rate)) # Conversion sécurisée en Decimal
    
    # 3. Calcul
    for p in packages:
        # p.prix est déjà un Decimal, maintenant on multiplie deux Decimals
        p.prix_eur = (p.prix * rate_decimal).quantize(Decimal('0.01'))
    
    # 4. Passage au template
    context = {
        'package': packages
    }
    
    return render(request, template, context)


