def ActivePackageUser(request):
    try:
        # 1. Récupération des données
        institution_id = request.POST.get('institution')
        old_inst_id = int(institution_id)
        
        old_inst = get_object_or_404(Institution, id=old_inst_id)
        personnel = request.user.personnel

        # 2. Vérification abonnement
        abonnement_actif = Abonnement.objects.filter(
            client=personnel, est_actif=True, date_fin__gte=timezone.now()
        ).select_related('package').first()

        if not abonnement_actif:
            messages.error(request, "Aucun abonnement actif.")
            return redirect('/payment/')
        
        package = abonnement_actif.package

        # 3. Transaction Atomique
        with db_transaction.atomic():
            
            # ÉTAPE A : Nouvelle Institution (Génère le nouvel ID)
            new_inst = Institution.objects.get(id=old_inst_id)
            new_inst.pk = None 
            new_inst.nom = f"{old_inst.nom} (Nouveau)"
            new_inst.is_active = True
            new_inst.save() 
            
            NOUVEL_ID_INSTITUTION = new_inst.id 

            # Sécurité mémoire
            old_inst = Institution.objects.get(id=old_inst_id)
            personnel.actual_institution = new_inst
            personnel.save()

            # =========================================================================
            # ÉTAPE B : DUPLICATION SANS BLOCAGE DES TYPES ET ENTITÉS
            # =========================================================================
            entity_mapping = {}

            # Récupérer les pivots de l'ancienne institution
            old_relations = InsitutionEntities.objects.filter(m_institution=old_inst).select_related('m_entity_type')
            
            for rel in old_relations:
                old_type = rel.m_entity_type
                if old_type:
                    # 1. Duplication du Type d'entité
                    old_type_id = old_type.id
                    new_type = old_type
                    new_type.pk = None  
                    if hasattr(new_type, 'm_nom') and new_type.m_nom:
                        new_type.m_nom = f"{new_type.m_nom} (Nouveau)"
                    new_type.save()

                    # 2. FILTRE SÉCURISÉ : On prend toutes les entités de ce type
                    # (On ne filtre plus strictement sur structure_responsable au cas où elle est vide)
                    entities = Entity.objects.filter(m_type_entity_id=old_type_id)

                    for entity in entities:
                        if entity.id not in entity_mapping:
                            old_entity_id = entity.id
                            
                            entity.pk = None  # Clone l'entité
                            if entity.m_nom:
                                entity.m_nom = f"{entity.m_nom} (Nouveau)"
                            
                            # Réassignation du type dupliqué
                            entity.m_type_entity_id = new_type.id
                            
                            # MISE À JOUR DYNAMIQUE : On remplace l'ancien ID partout où il se trouve
                            if entity.structure_responsable_id == old_inst_id or entity.structure_responsable_id is None:
                                entity.structure_responsable_id = NOUVEL_ID_INSTITUTION
                                
                            if entity.structure_accountable_id == old_inst_id or entity.structure_accountable_id is None:
                                entity.structure_accountable_id = NOUVEL_ID_INSTITUTION
                                
                            if entity.structure_consulted_id == old_inst_id:
                                entity.structure_consulted_id = NOUVEL_ID_INSTITUTION
                                
                            if entity.structure_informed_id == old_inst_id:
                                entity.structure_informed_id = NOUVEL_ID_INSTITUTION
                                
                            entity.save()
                            entity_mapping[old_entity_id] = entity

                    # 3. Sauvegarde de la table pivot
                    datasets = list(rel.dataset.all())
                    rel.pk = None
                    rel.m_institution = new_inst  
                    rel.m_entity_type = new_type   
                    rel.save()
                    rel.dataset.set(datasets)

            # =========================================================================
            # ÉTAPE C : HIÉRARCHIES
            # =========================================================================
            if entity_mapping:
                all_hierarchies = EntityHierachie.objects.filter(
                    m_sup_entity_id__in=entity_mapping.keys(),
                    m_sub_entity_id__in=entity_mapping.keys()
                )
                for hierachie in all_hierarchies.distinct():
                    new_sup = entity_mapping.get(hierachie.m_sup_entity_id)
                    new_sub = entity_mapping.get(hierachie.m_sub_entity_id)
                    EntityHierachie.objects.create(m_sup_entity=new_sup, m_sub_entity=new_sub)

            # =========================================================================
            # ÉTAPE D : RÔLES ET FONCTIONS
            # =========================================================================
            for role in Role.objects.filter(actual_institution=old_inst):
                old_role_id = role.pk
                role.pk = None
                if hasattr(role, 'nom') and role.nom:
                    role.nom = f"{role.nom} (Nouveau)"
                elif hasattr(role, 'm_nom') and role.m_nom:
                    role.m_nom = f"{role.m_nom} (Nouveau)"
                role.actual_institution = new_inst  
                role.save()
                
                for func in Personnel_Function.objects.filter(m_institution=old_inst, m_role_id=old_role_id):
                    func.pk = None
                    func.m_institution = new_inst  
                    func.m_role = role  
                    if hasattr(func, 'nom') and func.nom:
                        func.nom = f"{func.nom} (Nouveau)"
                    func.save()

            # =========================================================================
            # ÉTAPE E : INDICATEURS
            # =========================================================================
            for ind in Indicateur.objects.filter(m_institution=old_inst):
                ind.pk = None
                ind.m_institution = new_inst  
                if hasattr(ind, 'nom') and ind.nom:
                    ind.nom = f"{ind.nom} (Nouveau)"
                elif hasattr(ind, 'm_nom') and ind.m_nom:
                    ind.m_nom = f"{ind.m_nom} (Nouveau)"
                ind.save()

            # ÉTAPE F : Nouvel abonnement en attente
            date_fin = timezone.now() + timedelta(days=package.duree_jours)
            Abonnement.objects.create(
                client=personnel, package=package, date_fin=date_fin,
                est_actif=False, img=request.FILES.get('proof_file')
            )

        messages.success(request, f"Duplication réussie. Nouvel ID : {NOUVEL_ID_INSTITUTION}")
        return redirect('/')

    except Exception as e:
        messages.error(request, f"Erreur : {e}")
        return redirect(request.META.get('HTTP_REFERER', '/'))
