def process_paiement(request):
    if request.method != "POST":
        return JsonResponse({'success': False, 'message': 'Méthode invalide'}, status=405)

    try:
        # Enregistrement sécurisé en base de données
        with db_transaction.atomic():
            email = request.POST.get('email')
            name = request.POST.get('nom')
            telephone = request.POST.get('telephone')
            duree = int(request.POST.get('duree', 1))
            package_id = request.POST.get('package_id')
            file = request.FILES.get('preuve_paiement')

            # Gestion User & Personnel (Récupère s'il existe, crée sinon)
            user, created = User.objects.get_or_create(username=email, defaults={'email': email})
            
            personnel, created_p = Personnel.objects.get_or_create(
                mail=email, 
                defaults={'nom': name, 'tel': telephone, 'bd_user': user}
            )
            
            # --- CODE MODIFIÉ ---
            # Si le personnel existe déjà (not created_p), on ne fait rien.
            # On n'écrase plus son nom ni son téléphone.
            # On utilise directement ses infos existantes pour le mail de notification.
            nom_pour_notification = personnel.nom
            tel_pour_notification = personnel.tel
            # --------------------
            
            # Création Abonnement (S'ajoute dans tous les cas)
            package = Package.objects.get(id=package_id)
            montant_final = package.prix * duree
            montant_remise = (montant_final * package.remise) / 100

            net_a_payer = montant_final - montant_remise
            
            abonnement = Abonnement.objects.create(
                client=personnel,
                package=package,
                duree=duree,
                montant=net_a_payer,
                img=file,
                date_fin=timezone.now() + relativedelta(months=duree)
            )

            # Sécurité : On attend que le commit en BD soit REUSSI avant d'envoyer le mail
            db_transaction.on_commit(lambda: send_notifications.delay(
                nom_client=nom_pour_notification, # Utilise le nom réel en BD
                email=email,
                telephone=tel_pour_notification, # Utilise le tel réel en BD
                package_nom=package.nom, 
                duree=duree,
                montant_final=montant_final
            ))

        return JsonResponse({
            'success': True, 
            'message': 'Votre commande est bien enregistrée. Votre paiement est en cours de vérification. Vous recevrez un mail de confirmation sous peu.'
        })

    except Package.DoesNotExist:
        return JsonResponse({'success': False, 'message': 'Le package demandé n\'existe pas.'}, status=404)
    except Exception as e:
        print(f"Erreur système : {e}")
        return JsonResponse({'success': False, 'message': 'Une erreur est survenue lors de la soumission.'}, status=400)
def valid_process_paiement(request):
    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Méthode non autorisée.'}, status=405)

    try:
        # Récupération et validation sécurisée
        package_id = request.POST.get('package_id')
        duree = int(request.POST.get('duree', 0))
        file = request.FILES.get('preuve_paiement') # Récupération correcte du fichier

        if not all([package_id, duree, file]):
            return JsonResponse({'success': False, 'message': 'Données manquantes.'}, status=400)

        package = get_object_or_404(Package, id=package_id)
        montant_final = package.prix * duree

        # Utilisation de transaction pour l'atomicité
        with db_transaction.atomic():
            abonnement = Abonnement.objects.create(
                client=request.user.personnel,
                package=package,
                duree=duree,
                montant=montant_final,
                img=file,
                date_fin=timezone.now() + relativedelta(months=duree)
            )

        # Envoi d'email (Hors transaction)
        # Note : Pour une vraie application de production, utilisez une file d'attente (Celery)
        try:
            send_mail(
                subject=f"Nouvel abonnement : {request.user.username}",
                message=f"Détails de l'abonnement...\nClient : {request.user.personnel}\nMontant : {montant_final}",
                from_email=settings.DEFAULT_FROM_EMAIL,
                recipient_list=['dairounjankouo2019@gmail.com', 'henockmfouapon3@gmail.com'],
                fail_silently=False,
            )
        except Exception as e:
            # Log l'erreur mais ne bloque pas l'utilisateur
            print(f"Erreur envoi email : {e}")

        return JsonResponse({
            'success': True, 
            'message': 'Votre commande est enregistrée et en cours de vérification.'
        })

    except Exception as e:
        print(f"Erreur système : {e}")
        return JsonResponse({'success': False, 'message': 'Une erreur est survenue.'}, status=500)
def priorisation(request):
    template = 'priorisation.html'
    
    # 1. Récupération du contexte global (votre fonction basis)
    base_context = basis(request)
    actual_institution = base_context.get('actual_institution')
    
    # 2. Récupération des opérations triées (les priorités HAUTE en premier)
    # Note : Si vous utilisez des choix 'HAUTE', 'MOYENNE', 'FAIBLE', l'ordre alphabétique inverse (-priorite)
    # peut fonctionner, sinon triez par date ou par ID selon vos besoins.
    operation_list = Operation.objects.filter(m_institution=actual_institution).order_by('-id')
    
    # 3. Calcul dynamique des volumes pour la colonne de gauche (optionnel mais recommandé)
    # Cela permet d'avoir les vrais chiffres de la base de données
    count_haute = operation_list.filter(priorite='HAUTE').count()
    count_moyenne = operation_list.filter(priorite='MOYENNE').count()
    count_faible = operation_list.filter(priorite='FAIBLE').count()
    
    # 4. Gestion de la pagination (10 éléments par page)
    paginator = Paginator(operation_list, 10)
    page_number = request.GET.get('page')
    
    try:
        operation_page = paginator.get_page(page_number)
    except PageNotAnInteger:
        operation_page = paginator.page(1)
    except EmptyPage:
        operation_page = paginator.page(paginator.num_pages)

    # 5. Construction du contexte final
    context = {
        'actual_institution': actual_institution,
        'operation': operation_page,
        'count_haute': count_haute,
        'count_moyenne': count_moyenne,
        'count_faible': count_faible,
    }

    return render(request, template, context)


@require_POST
def priorisation_update(request):
    """
    Vue asynchrone (AJAX) déclenchée par le bouton H, M ou F du template.
    Modifie la priorité d'une opération et renvoie une réponse JSON.
    """
    try:
        # Extraction des données JSON envoyées par JavaScript
        data = json.loads(request.body)
        operation_id = data.get('id')
        nouvelle_priorite = data.get('priorite')  # Reçoit 'HAUTE', 'MOYENNE' ou 'FAIBLE'
        
        if not operation_id or not nouvelle_priorite:
            return JsonResponse({'error': 'Données incomplètes.'}, status=400)
            
        # Récupération et mise à jour de l'instance
        operation = Operation.objects.get(id=operation_id)
        operation.priorite = nouvelle_priorite
        operation.save()
        
        return JsonResponse({'status': 'success', 'message': 'Priorité mise à jour avec succès.'})
        
    except Operation.DoesNotExist:
        return JsonResponse({'error': 'Opération introuvable.'}, status=404)
    except Exception as e:
        return JsonResponse({'error': str(e)}, status=500)



def delete_categorie_archive(request, id):
    # 1. Récupération de la catégorie par son ID
    categorie = get_object_or_404(Categorie, id=int(id))
    
    # 2. Capturer la page précédente pour une redirection fluide
    next_url = request.META.get('HTTP_REFERER', '/')
    
    # 3. Vérification des liaisons en utilisant le champ exact 'categorie_id' (ou 'categorie')
    # On regarde si des sous-catégories pointent vers l'ID de cette catégorie
    a_des_sous_categories = Sous_categorie.objects.filter(categorie_id=categorie.id).exists()
    
    if a_des_sous_categories:
        messages.error(
            request, 
            f"Suppression impossible : La catégorie '{categorie.nom}' contient encore des sous-catégories associées."
        )
        return redirect(next_url)

    # 4. S'il n'y a aucune sous-catégorie liée, on procède à la suppression
    try:
        categorie.delete()
        messages.success(request, 'La catégorie a été supprimée avec succès !')
    except Exception as e:
        messages.error(request, f"Une erreur technique est survenue lors de la suppression : {e}")
        
    return redirect(next_url)


