def save_fields(request):
    if request.method == 'POST':
        noms = request.POST.getlist('field_name[]')
        types = request.POST.getlist('field_type[]')
        context = basis(request)
        actual_institution=context.get('actual_institution')
        
        # Utilisez une transaction pour garantir que si ça plante, rien n'est enregistré
        with db_transaction.atomic():
            # 1. Suppression des anciens champs pour cette institution
            FieldsTaks.objects.filter(institution=actual_institution).delete()
            
            # 2. Recréation propre des champs reçus
            for nom, type_val in zip(noms, types):
                if nom.strip():
                    FieldsTaks.objects.create(
                        name=nom,
                        type=type_val,
                        institution=actual_institution
                    )
        
        return redirect(request.META.get('HTTP_REFERER','/'))



