def search_etape(request):
    nature_id = request.GET.get('nature')
    intensite = request.GET.get('intensite')
    
    context = basis(request)
    etapes = Etape.objects.filter(institution=context['actual_institution'])

    if nature_id:
        etapes = etapes.filter(nature=nature_id)

    # Calcul dynamique de la somme
    field = get_duree_field(intensite)
    total_duration = 0
    if field:
        # Aggregate directement sur le queryset filtré
        total_duration = etapes.aggregate(total=Sum(field))['total'] or 0
        etapes = etapes.filter(**{f"{field}__gt": 0})

    context.update({'etapes': etapes, 'intensite': intensite, 'total_duration': total_duration})
    return render(request, 'etapes.html', context)
