def save_operation_step(request):
    context = basis(request)
    actual_institution = context.get('actual_institution')
    
    # Détection de la requête Fetch/AJAX
    is_ajax = request.headers.get('Accept') == 'application/json'

    try:
        r_tache_id = request.POST.get('tache')
        r_tache = Tache.objects.get(id=int(r_tache_id))
        
        # Helper pour récupérer le personnel
        def get_person(key):
            val = request.POST.get(key, "0")
            return Personnel.objects.get(id=int(val)) if val != "0" else None

        r_perso = get_person('perso')
        r_accountable = get_person('accountable')
        r_consulted = get_person('consulted')
        r_informed = get_person('informed')
        source_ids = request.POST.getlist('source_financement')


        # Dates et infos de base
        date_debut = request.POST.get('date_debut', '').strip()
        date_echeance_str = request.POST.get('date_echeance', '').strip()
        mois = request.POST.get('mois')
        structure_id = request.POST.get('structure', '').strip()
        
        instance_structure = None
        if structure_id and structure_id.isdigit():
            instance_structure = Structure.objects.get(id=int(structure_id))

        # Logique financière et pondération
        total_financement = Decimal(request.POST.get('total_financement', '0') or '0')
        all_operations = Operation.objects.filter(tache=r_tache)
        new_count = all_operations.count() + 1
        new_ponderation = 100 / new_count
        all_operations.update(ponderation=new_ponderation)

        # Création de l'opération
        operation = Operation.objects.create(
            tache=r_tache,
            nom=request.POST.get('nom'),
            notification=request.POST.get('notification'),
            priorite=request.POST.get('priorite'),
            date_echeance=date_echeance_str if date_echeance_str else None,
            date_debut=date_debut if date_debut else None,
            nature_operation_id=request.POST.get('nature'),
            categorie_id=request.POST.get('categorie'),
            structure=instance_structure,
            periode_ok_id=mois,
            parent_id=request.POST.get('operation_id'),
            ponderation=new_ponderation,
            
            montant_total_source_financement=total_financement,
            personnel=r_perso,
            accountable=r_accountable,
            consulted=r_consulted,
            informed=r_informed,
            m_institution = actual_institution,
            poceded_step=True
           
        )


        if 'file_oko' in request.FILES:
            operation.fichier_joint = request.FILES['file_oko']
            operation.save()

        # Mise à jour de la hiérarchie financière
        def update_hierarchy(current_entity, added_amount):
            current_entity.montant_planifiee = (current_entity.montant_planifiee or 0) + added_amount
            current_entity.save()
            parents = EntityHierachie.objects.filter(m_sub_entity=current_entity)
            for rel in parents:
                update_hierarchy(rel.m_sup_entity, added_amount)

        update_hierarchy(r_tache, total_financement)
        data_to_send = {}
        
        for s_id in source_ids:
            montant = request.POST.get(f'montant_source_{s_id}', '0')
            data_to_send[s_id] = montant

        # 3. Envoi au broker Redis (.delay ne bloque pas l'utilisateur)
        async_register_sources_financement.delay(
            operation.id, 
            actual_institution.id, 
            data_to_send
        )

        etapes_ids = request.POST.getlist('etape_ids')

        
        for etape_id in etapes_ids:
            duree = request.POST.get(f'duree_{etape_id}')
            date_fin = request.POST.get(f'date_fin_{etape_id}')
            progression = request.POST.get(f'progression_{etape_id}')
            
            # Validation simple
            if date_fin:
                # Sauvegarde ou mise à jour
                obj, created = IndicateurValeur.objects.update_or_create(
                    etape_id=etape_id,
                    defaults={
                        'duree': duree,
                        'date_enregistrement': date_fin,
                        'valeur': progression,
                        'operation': operation,
                    }
                )
            
        send_operation_mail.delay(operation.id)

        if is_ajax:
            return JsonResponse({'status': 'success', 'tache_id': r_tache.id})
        
        return redirect(f"/taches/{r_tache.id}/")

    except Exception as e:
        if is_ajax:
            return JsonResponse({'status': 'error', 'message': str(e)}, status=400)
        return redirect(request.META.get('HTTP_REFERER','/'))

