import anthropic
@csrf_exempt
def api_chat(request):
    if request.method == 'POST':
        try:
            # 1. Récupérer le message et l'ID de l'indicateur
            data = json.loads(request.body)
            user_message = data.get('message', '')
            indicateur_id = data.get('indicateur_id')

            # 2. Interroger la table IndicateurValeur en filtrant par l'indicateur lié
            if indicateur_id:
                valeurs_indicateur = IndicateurValeur.objects.select_related('indicateur', 'periode_ok').filter(indicateur_id=indicateur_id).order_by('-date_enregistrement')[:5]
            else:
                valeurs_indicateur = IndicateurValeur.objects.select_related('indicateur', 'periode_ok').all().order_by('-date_enregistrement')[:5]
            
            # 3. Sérialiser les données selon les champs réels de votre modèle
            donnees_contexte = []
            for iv in valeurs_indicateur:
                donnees_contexte.append({
                    "nom_valeur": iv.nom,
                    "indicateur": iv.indicateur.m_name if iv.indicateur else "N/A",
                    "periode": str(iv.periode_ok) if iv.periode_ok else "N/A",
                    "valeur": str(iv.valeur) if iv.valeur else "N/A",
                    "valeur_cumulee": iv.valeur_cumulee,
                    "valeur_moyenne": iv.valeur_moyenne,
                    "type_donnee": iv.type_donnee,
                    "reference_cible": iv.reference_cible,
                    "date_saisie": str(iv.date_saisie) if iv.date_saisie else "N/A"
                })

            # 4. Initialiser le client Anthropic
            client = anthropic.Anthropic()

            # 5. Construire le prompt utilisateur avec le contexte des valeurs
            prompt_utilisateur = f"""
            Contexte des données de la table IndicateurValeur :
            {json.dumps(donnees_contexte, ensure_ascii=False, indent=2)}

            Message de l'utilisateur : {user_message}
            """

            # 6. Appel à l'API Anthropic (Nom de modèle corrigé)
            response = client.messages.create(
                model="claude-3-5-sonnet-latest",
                max_tokens=1500,
                messages=[
                    {
                        "role": "user",
                        "content": prompt_utilisateur
                    }
                ]
            )

            # 7. Extraction sécurisée du texte (Gestion robuste des blocs multiples / ThinkingBlock)
            ai_reply = ""
            for block in response.content:
                if hasattr(block, 'text') and block.text:
                    ai_reply += block.text

            if not ai_reply:
                ai_reply = "Aucune réponse textuelle générée par le modèle."

            return JsonResponse({'reply': ai_reply})

            print(f"Erreur API Anthropic: {str(e)}") # Log optionnel dans la console
        except Exception as e:
            return JsonResponse({'reply': f"Erreur serveur lors du traitement : {str(e)}"}, status=500)

    return JsonResponse({'reply': "Méthode non autorisée."}, status=405)



