def SendAvis(request):
    if request.method == "POST":
        commentaire = request.POST.get('commentaire')
        fichier = request.FILES.get('piece_jointe')
        tache_id = request.POST.get('operation')
        
        instance_operation = get_object_or_404(Operation, id=int(tache_id))
        destinataire_mail = getattr(instance_operation.personnel, 'mail', None)
        
        # 1. Enregistrement dans la table HistoricRACI
        historic_entry = HistoricRACI.objects.create(
            m_operation=instance_operation,
            m_role=request.user,
            m_commentaire=commentaire,
            file=fichier,
            m_date_realisation=date.today()
        )

        emmetteur = getattr(instance_operation.consulted, 'mail', None)
        
        # 2. Envoi du mail HTML personnalisé
        if destinataire_mail:
            sujet = f"Nouvel avis sur la tâche : {instance_operation.nom}"
            
            # Données à injecter dans le template HTML
            contexte_email = {
                'operation': instance_operation,
                'commentaire': commentaire,
                'auteur_nom': emmetteur,
                'piece_jointe': fichier,  # On passe le fichier au contexte pour afficher son nom si besoin
            }
            
            # Rendu du template HTML en chaîne de caractères
            html_content = render_to_string('email/email_avis.html', contexte_email)
            text_content = strip_tags(html_content)
            
            # Création de l'e-mail enrichi
            email = EmailMultiAlternatives(
                subject=sujet,
                body=text_content,
                from_email=settings.DEFAULT_FROM_EMAIL,
                to=[destinataire_mail]
            )
            email.attach_alternative(html_content, "text/html")
            
            # AJOUT : Joindre le fichier au mail s'il est présent
            if fichier:
                # fichier.read() lit le contenu binaire, fichier.name donne le nom d'origine
                email.attach(fichier.name, fichier.read(), fichier.content_type)
            
            # Envoi effectif
            email.send(fail_silently=False)
            messages.success(request, "Votre Avis a ete Soumit")
        
        return redirect('/tache_consulted/')

    return redirect('/tache_consulted/')


